        cow.kind = crate::mob::MobKind::Cow;
        cow.on_ground = true;
        cow.health = 0.5; // the one dose the fire kills on
        cow.fire_ticks = 20;
        app.mobs.push(cow);
        let mut sheep =
            crate::mob::Zombie::new(8, c as f64 - 2.5, top as f64, c as f64 + 0.5, 4);
        sheep.kind = crate::mob::MobKind::Sheep;
        sheep.on_ground = true;
