    #[test]
    fn the_offline_arm_rides_when_the_chain_speaks_it() {
        // THE ONE-LIST WALK's own split: the offline body NEARER the
        // wire's — the chain index lands the offline side, the local
        // prediction rides (the health the client's own to mutate),
        // the Attack packet the press never speaks (the Swing the only
        // beat the lane carries).
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let n = app.world_size as f64;
        let mut body = crate::body::PlayerBody::new(
            n / 2.0 + 0.5,
            app.spawn_y as f64,
            n / 2.0 + 0.5,
            -90.0,
            0.0,
        );
        body.on_ground = true;
        app.body = Some(body);
        let (bx, bz) = {
            let b = app.body.as_ref().unwrap();
            (b.x, b.z)
        };
        // the wire body at 1.8 (the crosshair stage's own t), the
        // offline body NEARER at 1.5 — the chain's own order rides
        app.live_mobs_updated(vec![wire_mob_named(
            100,
            bx + 1.8,
            app.spawn_y as f64,
            bz,
            "minecraft:zombie",
        )]);
        app.mobs
            .push(crate::mob::Zombie::new(7, bx + 1.5, app.spawn_y as f64, bz, 3));
        let wire_health_before = app.net_mobs[0].health;
        let offline_health_before = app.mobs[0].health;
        let (tx, rx) = std::sync::mpsc::channel();
        app.live_clicks = Some(tx);
        app.on_attack();
        // THE OFFLINE ARM: the local prediction the health drop speaks;
        // the wire body the untouched mirror
        assert!(
            app.mobs[0].health < offline_health_before,
            "the offline body the local prediction owns"
        );
        assert_eq!(
            app.net_mobs[0].health, wire_health_before,
            "the wire body the offline prediction never touches"
        );
        // THE LANE: the Swing the only command — the Attack packet the
        // offline arm never mints
        assert_eq!(
            rx.try_recv().unwrap(),
            crate::world_view::ContainerCommand::Swing,
            "the offline arm the Swing alone speaks"
        );
        assert!(rx.try_recv().is_err(), "no Attack packet the offline press sends");
    }

    #[test]
    fn the_crit_hit_arms_the_damage_indicators() {
        // THE WIRING'S OWN TRUTH (damageStatsAndHearts at the attack
        // site): the crit's 3.0 dealt crosses the > 2.0 gate and lands
        // ONE indicator at the mob's mid height; the plain fist's 2.0
        // dealt stays under the gate — the honest vanilla shape
        let mut app = App::new(3);
        app.enter_world();
        crate::headless::seed_scene(
            &mut app,
            &crate::headless::SceneOpts {
                body: true,
                zombie: true,
                ..crate::headless::SceneOpts::default()
            },
        )
        .unwrap();
        let idx = 0;
        // THE REACH THE 26.2 LAW SPEAKS (the entity arm's own
        // filterHitResult): the crosshair's entity verdict only lands
        // inside the 3.0 entity_interaction_range — the ring's 4-east
        // staging sits OUTSIDE it, the mob snaps to 2.5 (the 2.5 the
        // attack tests stage) so the fist lands
        {
            let bx = app.body.as_ref().unwrap().x;
            app.mobs[idx].x = bx + 2.5;
        }
        // aim at the zombie's mid height (the vanilla getY(0.5) the
        // burst rides)
        {
            let (tx, ty, tz) = {
                let m = &app.mobs[idx];
                (m.x, m.y + crate::mob::ZOMBIE_HEIGHT * 0.5, m.z)
            };
            let b = app.body.as_mut().unwrap();
            let (dx, dy, dz) = (tx - b.x, ty - (b.y + b.eye_height()), tz - b.z);
            let horiz = (dx * dx + dz * dz).sqrt().max(1e-9);
            let len3 = (dx * dx + dy * dy + dz * dz).sqrt().max(1e-9);
            b.yaw = ((dx / horiz).atan2(-dz / horiz) - std::f64::consts::PI).to_degrees() as f32;
            b.pitch = -(dy / len3).asin().to_degrees() as f32;
        }
        // THE PLAIN FIST'S GATE: the full charge deals 2.0 — the dealt
        // stays at the gate's edge, no indicator spawns
        app.attack_ticker = 20;
        app.on_attack();
        let plain = app
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Damage))
            .count();
        assert_eq!(plain, 0, "the 2.0 dealt never crosses the gate");
        // THE CRIT'S OWN BURST: the fall distance arms the crit (the
        // 1.5x the damage law speaks — 3.0 dealt, the count-1 walk)
        app.mobs[idx].health = 10.0;
        {
            let b = app.body.as_mut().unwrap();
            b.fall_distance = 1.0;
            b.on_ground = false;
            b.sprinting = false;
        }
        app.attack_ticker = 20;
        app.on_attack();
        let stars = app
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Damage))
            .count();
        assert_eq!(stars, 1, "the 3.0 dealt speaks the count-1 walk");
        let m = &app.mobs[idx];
        for p in app
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Damage))
        {
            let mid = m.y + crate::mob::ZOMBIE_HEIGHT * 0.5;
            assert!(
                (p.y - mid).abs() <= 0.6,
                "the mid-height band the getY(0.5) speaks: {} vs {mid}",
                p.y
            );
            assert!(p.vy > 0.5, "the +1.0 burst rides: {}", p.vy);
            assert_eq!(p.lifetime, 20);
        }
    }

    #[test]
    fn the_sweep_hit_arms_the_arc_and_the_aoe() {
        // THE GATE'S OWN TRUTH (isSweepAttack at the attack site): the
        // full charge + the sword + the grounded still body speak the
        // sweep — the arc spawns ONE (the count-0 walk) at the body's
        // own mid height one forward block, the sweep voice logs, the
        // strong voice stays silent (the branch the attackVisualEffects
        // speaks); the bare fist's same swing never sweeps
        let mut app = App::new(3);
        app.enter_world();
        crate::headless::seed_scene(
            &mut app,
            &crate::headless::SceneOpts {
                body: true,
                zombie: true,
                ..crate::headless::SceneOpts::default()
            },
        )
        .unwrap();
        let idx = 0;
        // aim at the zombie's mid height (the crit test's own walk)
        {
            let (tx, ty, tz) = {
                let m = &app.mobs[idx];
                (m.x, m.y + crate::mob::ZOMBIE_HEIGHT * 0.5, m.z)
            };
            let b = app.body.as_mut().unwrap();
            let (dx, dy, dz) = (tx - b.x, ty - (b.y + b.eye_height()), tz - b.z);
            let horiz = (dx * dx + dz * dz).sqrt().max(1e-9);
            let len3 = (dx * dx + dy * dy + dz * dz).sqrt().max(1e-9);
            b.yaw = ((dx / horiz).atan2(-dz / horiz) - std::f64::consts::PI).to_degrees() as f32;
            b.pitch = -(dy / len3).asin().to_degrees() as f32;
        }
        // THE SWORD'S OWN GATE: the full charge + the grounded + the
        // sword speaks the sweep
        let sword = crate::mob::wire_id("iron_sword").expect("the sword rides the wire");
        app.inventory.items[app.selected_hotbar] = (sword, 1);
        app.attack_ticker = 20;
        app.on_attack();
        let arcs = app
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Sweep))
            .count();
        assert_eq!(arcs, 1, "the count-0 walk leaves ONE arc");
        // the arc's own pose: the body's mid height, one forward block
        // (the getX() - sin(yaw), getY(0.5), getZ() + cos(yaw) law)
        let (bxy, byy, bzy) = {
            let b = app.body.as_ref().unwrap();
            let vyaw = b.yaw as f64 * std::f64::consts::PI / 180.0;
            let (bx, by, bz) = (b.x, b.y, b.z);
            let mid = by + crate::body::STANDING_HEIGHT * 0.5;
            let arc = app
                .particles
                .iter()
                .find(|p| matches!(p.kind, crate::particles::ParticleKind::Sweep))
                .unwrap();
            let want = (bx - vyaw.sin(), mid, bz + vyaw.cos());
            assert!(
                (arc.x - want.0).abs() < 1e-9
                    && (arc.y - want.1).abs() < 1e-9
                    && (arc.z - want.2).abs() < 1e-9,
                "the arc pose the tail speaks: ({}, {}, {}) vs {:?}",
                arc.x,
                arc.y,
                arc.z,
                want
            );
            assert_eq!(arc.lifetime, 4, "the 4-tick life the ctor pins");
            (bx, by, bz)
        };
        let _ = (bxy, byy, bzy);
        // the sweep voice logged, the strong voice refused (the
        // attackVisualEffects branch the sweep suppresses)
        let sweep_voice = app
            .sounds
            .events
            .iter()
            .filter(|e| e.starts_with("entity.player.attack.sweep"))
            .count();
        assert_eq!(sweep_voice, 1, "the offset-0 voice the arm speaks");
        let strong_voice = app
            .sounds
            .events
            .iter()
            .any(|e| e.starts_with("entity.player.attack.strong"));
        assert!(!strong_voice, "the suppressed branch stays silent");
        // THE BARE FIST'S OWN REFUSAL: the same grounded full-charge
        // swing without the sword never sweeps (the SWORDS tag the
        // gate reads), the strong voice speaks instead
        app.inventory.items[app.selected_hotbar] = (sword, 0);
        app.attack_ticker = 20;
        app.on_attack();
        let arcs2 = app
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Sweep))
            .count();
        assert_eq!(arcs2, 1, "the fist's swing never adds an arc");
        let strong_voice2 = app
            .sounds
            .events
            .iter()
            .any(|e| e.starts_with("entity.player.attack.strong"));
        assert!(strong_voice2, "the unsuppressed branch speaks");
    }

    #[test]
    fn the_sweep_aoe_rides_the_inflated_box_and_the_nine_ring() {
        // THE AOE'S OWN TRUTH (doSweepAttack's neighbor walk): the
        // second zombie inside the target's inflate(1.0, 0.25, 1.0)
        // box and inside the 9.0 distance ring takes the swept hit
        // (the full total the no-enchants law speaks) and the
        // (0.4, sin, -cos) knockback; the far zombie outside the ring
        // stays clean
        let mut app = App::new(3);
        app.enter_world();
        crate::headless::seed_scene(
            &mut app,
            &crate::headless::SceneOpts {
                body: true,
                zombie: true,
                ..crate::headless::SceneOpts::default()
            },
        )
        .unwrap();
        let idx = 0;
        // aim at the zombie's mid height
        {
            let (tx, ty, tz) = {
                let m = &app.mobs[idx];
                (m.x, m.y + crate::mob::ZOMBIE_HEIGHT * 0.5, m.z)
            };
            let b = app.body.as_mut().unwrap();
            let (dx, dy, dz) = (tx - b.x, ty - (b.y + b.eye_height()), tz - b.z);
            let horiz = (dx * dx + dz * dz).sqrt().max(1e-9);
            let len3 = (dx * dx + dy * dy + dz * dz).sqrt().max(1e-9);
            b.yaw = ((dx / horiz).atan2(-dz / horiz) - std::f64::consts::PI).to_degrees() as f32;
            b.pitch = -(dy / len3).asin().to_degrees() as f32;
        }
        // the stage's own geometry: the target exactly 2.0 out along
        // the facing (the seed's own east stance), the NEIGHBOR beside
        // it 0.7 lateral (inside the inflated box + the 9.0 ring,
        // clear of the aim ray), the FAR one 4.5 out behind it
        // (outside the 9.0 ring — dist² 42.25)
        let (nx, nz) = {
            let b = app.body.as_ref().unwrap();
            let vyaw = b.yaw as f64 * std::f64::consts::PI / 180.0;
            let fx = -vyaw.sin();
            let fz = vyaw.cos();
            let m = &mut app.mobs[idx];
            m.x = b.x + fx * 2.0;
            m.z = b.z + fz * 2.0;
            (m.x + fz * 0.7, m.z - fx * 0.7)
        };
        let neighbor = crate::mob::Zombie::new(2, nx, app.mobs[idx].y, nz, 311);
        let neighbor_health = neighbor.health;
        app.mobs.push(neighbor);
        let far_health = {
            let (tx, ty, tz) = (app.mobs[idx].x, app.mobs[idx].y, app.mobs[idx].z);
            let b = app.body.as_ref().unwrap();
            let vyaw = b.yaw as f64 * std::f64::consts::PI / 180.0;
            let (fx, fz) = (-vyaw.sin(), vyaw.cos());
            let far = crate::mob::Zombie::new(
                3,
                tx + fx * 4.5,
                ty,
                tz + fz * 4.5,
                313,
            );
            let fh = far.health;
            app.mobs.push(far);
            fh
        };
        // aim at the zombie's mid height (AFTER the staging sits)
        {
            let (tx, ty, tz) = {
                let m = &app.mobs[idx];
                (m.x, m.y + crate::mob::ZOMBIE_HEIGHT * 0.5, m.z)
            };
            let b = app.body.as_mut().unwrap();
            let (dx, dy, dz) = (tx - b.x, ty - (b.y + b.eye_height()), tz - b.z);
            let horiz = (dx * dx + dz * dz).sqrt().max(1e-9);
            let len3 = (dx * dx + dy * dy + dz * dz).sqrt().max(1e-9);
            b.yaw = ((dx / horiz).atan2(-dz / horiz) - std::f64::consts::PI).to_degrees() as f32;
            b.pitch = -(dy / len3).asin().to_degrees() as f32;
        }
        // the sword + the full charge + the grounded swing
        let target_health = app.mobs[idx].health;
        let sword = crate::mob::wire_id("iron_sword").expect("the sword rides the wire");
        app.inventory.items[app.selected_hotbar] = (sword, 1);
        app.attack_ticker = 20;
        app.on_attack();
        // the neighbor took the swept hit: the full-charge sword
        // speaks the 2.0 total the ATTACK_DAMAGE law deals
        let nh = app.mobs[1].health;
        assert!(
            nh < neighbor_health,
            "the neighbor takes the swept hit: {nh} < {neighbor_health}"
        );
        // the full total the no-enchants law speaks: the swept hit
        // deals the SAME the direct hit dealt (the attack's own total
        // through the same hurt law — the zombie's ARMOR 2.0 fold the
        // CombatRules walk speaks applies to both alike)
        let target_delta = target_health - app.mobs[idx].health;
        assert!(
            ((neighbor_health - nh) - target_delta).abs() < 1e-6,
            "the swept hit deals the full total: {} vs {target_delta}",
            neighbor_health - nh
        );
        // the far zombie never heard of it
        assert_eq!(app.mobs[2].health, far_health, "the 9.0 ring holds");
        // the neighbor's knockback: the minus law pushed it along the
        // facing (the vx it carries away)
        let _ = (nx, nz);
    }

    #[test]
    fn the_ambient_walk_spawns_the_pool_drips() {
        // THE STAGE'S OWN TRUTH: the lava pool + the 24-tick walk —
        // the 667x2 sampler lands the pool's 9 surface cells, the
        // 1/100 gate fires the drips (the 8x8 sprite's surface Y the
        // +1.0 speaks), the voices log the two formulas
        let mut app = App::new(3);
        app.enter_world();
        crate::headless::seed_scene(
            &mut app,
            &crate::headless::SceneOpts {
                body: true,
                lava_pool: true,
                particles: Some("lava".into()),
                ..crate::headless::SceneOpts::default()
            },
        )
        .unwrap();
        let drips = app
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Lava))
            .count();
        assert!(drips > 0, "the walk fires on the pool's surface: {drips}");
        // the surface Y: the pool's top cells speak floor+1.0 — every
        // drip's birth Y rides the band the carve's level names
        for p in app.particles.iter() {
            if matches!(p.kind, crate::particles::ParticleKind::Lava) {
                // the spawn band 0.05..0.45 DECAYS the staged flight's
                // three ticks speak (0.04 * 0.75 per tick) — the
                // post-flight band rides it
                assert!(
                    p.vy >= -0.05 && p.vy < 0.4,
                    "the pop band the ctor speaks: {}",
                    p.vy
                );
                assert_eq!(p.gravity, 0.75);
            }
            if matches!(p.kind, crate::particles::ParticleKind::Smoke) {
                assert_eq!(p.gravity, -0.1, "the child RISES");
                assert!(p.col[0] <= 0.3, "the grey tint's band");
            }
        }
        // the voices: the pop + the ambient formulas ride the log
        let pops = app
            .sounds
            .events
            .iter()
            .filter(|e| e.starts_with("block.lava.pop @"))
            .count();
        assert!(pops > 0, "the pop voice the gate speaks: {pops}");
        for e in app.sounds.events.iter() {
            if let Some((v, p)) = e
                .split_once(" v")
                .and_then(|(_, rest)| rest.split_once(" p"))
            {
                if e.starts_with("block.lava.pop") || e.starts_with("block.lava.ambient") {
                    let vol: f32 = v.parse().unwrap();
                    let pitch: f32 = p.parse().unwrap();
                    assert!(
                        (0.2..0.4).contains(&vol),
                        "the volume formula's band: {vol}"
                    );
                    assert!(
                        (0.9..1.05).contains(&pitch),
                        "the pitch formula's band: {pitch}"
                    );
                }
            }
        }
        // the replay: the same app walks the same seeds — the two
        // streams' determinism the shots ride
        let mut a = App::new(3);
        a.enter_world();
        crate::headless::seed_scene(
            &mut a,
            &crate::headless::SceneOpts {
                body: true,
                lava_pool: true,
                particles: Some("lava".into()),
                ..crate::headless::SceneOpts::default()
            },
        )
        .unwrap();
        let mut b = App::new(3);
        b.enter_world();
        crate::headless::seed_scene(
            &mut b,
            &crate::headless::SceneOpts {
                body: true,
                lava_pool: true,
                particles: Some("lava".into()),
                ..crate::headless::SceneOpts::default()
            },
        )
        .unwrap();
        let da: Vec<(u32, f64, f64, f64)> = a
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Lava))
            .map(|p| (p.lifetime, p.x, p.y, p.z))
            .collect();
        let db: Vec<(u32, f64, f64, f64)> = b
            .particles
            .iter()
            .filter(|p| matches!(p.kind, crate::particles::ParticleKind::Lava))
            .map(|p| (p.lifetime, p.x, p.y, p.z))
            .collect();
        assert_eq!(da, db, "the seeded walk replays");
    }

    #[test]
    fn the_column_ambient_walk_speaks_the_column_cells() {
        // THE WHIRLPOOL'S OWN WORLD (every cell the 15294 id names —
        // the sampler cannot miss): the walk answers ONE CURRENT_DOWN
        // per in-bounds sample, the fixed (x+0.5, y+0.8, z+0.5) birth
        // the addAlwaysVisibleParticle call speaks, the 1/200 rolls
        // firing the whirlpool's ambient voice
        let stamp = |id: u16| -> crate::world::World {
            let mut world = crate::world::World::new(1, 0);
            world.variants = Some(vec![vec![0u8; 16 * 48 * 16]; 1]);
            for y in 0..48 {
                for z in 0..16 {
                    for x in 0..16 {
                        world.set(x, y, z, id);
                    }
                }
            }
            world
        };
        let mut app = App::new(3);
        app.offline_world = Some(stamp(15294));
        let out = app.animate_tick_walk((8.0, 12.0, 8.0));
        assert!(!out.is_empty(), "the column cells answer the walk");
        for p in out.iter() {
            assert!(
                matches!(p.kind, crate::particles::ParticleKind::CurrentDown),
                "the whirlpool's own droplet"
            );
            assert_eq!(p.vy, -0.05, "the fixed birth speed");
            assert_eq!(p.gravity, 0.002);
            assert!((30..=90).contains(&p.lifetime), "the (int)(r*60)+30 band");
            // the fixed offsets: the fractional .5/.8 the cell coords
            // speak — no offset draws the whirlpool's arm keeps
            assert_eq!(p.x.fract(), 0.5, "the x+0.5 the call speaks");
            assert_eq!(p.z.fract(), 0.5, "the z+0.5 the call speaks");
            assert!((p.y.fract() - 0.8).abs() < 1e-9, "the y+0.8 the call speaks");
        }
        // the voices: the whirlpool event the 1/200 gate speaks, the
        // volume/pitch formula's bands the log's ` v.. p..` tail keeps
        let mut voices = 0;
        for e in app.sounds.events.iter() {
            if !e.starts_with("block.bubble_column.whirlpool_ambient @") {
                continue;
            }
            voices += 1;
            if let Some((v, p)) = e
                .split_once(" v")
                .and_then(|(_, rest)| rest.split_once(" p"))
            {
                let vol: f32 = v.parse().unwrap();
                let pitch: f32 = p.parse().unwrap();
                assert!(
                    (0.2..0.4).contains(&vol),
                    "the volume formula's band: {vol}"
                );
                assert!(
                    (0.9..1.05).contains(&pitch),
                    "the pitch formula's band: {pitch}"
                );
            }
        }
        assert!(voices > 0, "the whirlpool's ambient voice fires: {voices}");
        // the replay: the same stamps walk the same seeds
        let mut a = App::new(3);
        a.offline_world = Some(stamp(15294));
        let da: Vec<(u32, f64, f64, f64)> = a
            .animate_tick_walk((8.0, 12.0, 8.0))
            .iter()
            .map(|p| (p.lifetime, p.x, p.y, p.z))
            .collect();
        let mut b = App::new(3);
        b.offline_world = Some(stamp(15294));
        let db: Vec<(u32, f64, f64, f64)> = b
            .animate_tick_walk((8.0, 12.0, 8.0))
            .iter()
            .map(|p| (p.lifetime, p.x, p.y, p.z))
            .collect();
        assert_eq!(da, db, "the seeded walk replays");
        // THE UPWARD'S OWN WORLD: TWO bubbles per sampled cell — the
        // first at the fixed corner (x+0.5, y, z+0.5), the second's
        // offsets the block stream draws inside the same cell
        let mut app2 = App::new(3);
        app2.offline_world = Some(stamp(15295));
        let out2 = app2.animate_tick_walk((8.0, 12.0, 8.0));
        assert!(!out2.is_empty(), "the upward cells answer the walk");
        assert_eq!(out2.len() % 2, 0, "two bubbles per sampled cell");
        for pair in out2.chunks(2) {
            assert!(
                matches!(pair[0].kind, crate::particles::ParticleKind::BubbleColumnUp),
                "the upward's own bubble"
            );
            assert_eq!(pair[0].x.fract(), 0.5, "the fixed corner birth");
            assert_eq!(pair[0].y.fract(), 0.0, "the raw y the corner keeps");
            assert_eq!(pair[0].z.fract(), 0.5, "the fixed corner birth");
            assert!(
                ((pair[0].vy - 0.008).abs() <= 0.02),
                "the push's fifth ± the jitter band: {}",
                pair[0].vy
            );
            assert_eq!(pair[0].gravity, -0.125, "the rise the base lane turns");
            assert_eq!(pair[0].friction, 0.85);
            assert!((40..=200).contains(&pair[0].lifetime), "the 40.0 fold's band");
            // the second rides the SAME cell: the offsets the [0,1)
            // band holds — x/z within ±0.5 of the corner birth, y
            // within [y, y+1)
            assert!(pair[1].x >= pair[0].x - 0.5 && pair[1].x < pair[0].x + 0.5);
            assert!(pair[1].y >= pair[0].y && pair[1].y < pair[0].y + 1.0);
            assert!(pair[1].z >= pair[0].z - 0.5 && pair[1].z < pair[0].z + 0.5);
        }
        // the upward's voice: the sibling event the 1/200 gate speaks
        let up_voices = app2
            .sounds
            .events
            .iter()
            .filter(|e| e.starts_with("block.bubble_column.upwards_ambient @"))
            .count();
        assert!(up_voices > 0, "the upward's ambient voice fires: {up_voices}");
        // the plain world's silence (the honest no-column answer):
        // water everywhere, the variants layer zero — no spawns, no
        // voices
        let mut app3 = App::new(3);
        app3.offline_world = Some(stamp(crate::world::WATER));
        let out3 = app3.animate_tick_walk((8.0, 12.0, 8.0));
        assert!(out3.is_empty(), "the plain water the column answer skips");
        assert!(
            !app3
                .sounds
                .events
                .iter()
                .any(|e| e.contains("bubble_column")),
            "no column voice the plain world keeps"
        );
    }

    /// THE E KEY'S OWN LANE: the world screen opens the survival
    /// inventory, the inventory screen closes it back (E and Escape
    /// both), the death gate keeps the DeathScreen modal, and the
    /// vanilla inventory never pauses the world (the container's own
    /// law — the pause flag the open never touches).
    #[test]
    fn the_e_key_opens_and_closes_the_inventory() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.on_inventory_key();
        assert_eq!(app.screen, ScreenKind::Inventory, "E opens over the world");
        assert!(!app.paused, "the vanilla inventory never pauses");
        assert_eq!(app.inv_carried, (0, 0), "the carried fresh-empty");
        // the frozen-container convention: the body's tick gate reads
        // the screen (the World test the gate's own arm speaks)
        assert_ne!(app.screen, ScreenKind::World);
        // the E key's second half: back to the world
        app.on_inventory_key();
        assert_eq!(app.screen, ScreenKind::World, "E closes it back");
        // the Escape arm on the open screen
        app.on_inventory_key();
        assert_eq!(app.screen, ScreenKind::Inventory);
        app.on_escape();
        assert_eq!(app.screen, ScreenKind::World, "Escape closes too");
        // THE DEATH GATE: a dead player's E never opens
        app.dead = true;
        app.on_inventory_key();
        assert_eq!(app.screen, ScreenKind::World, "the DeathScreen stays modal");
        assert_ne!(app.screen, ScreenKind::Inventory);
        // the OTHER screens ignore the key (the screen stack's own law)
        app.dead = false;
        app.screen = ScreenKind::Servers;
        app.on_inventory_key();
        assert_eq!(app.screen, ScreenKind::Servers, "no inventory over the list");
    }

    /// THE INVENTORY'S OWN CLICK WALK: the left press's pickup / place /
    /// merge / swap over the REAL store (the doClick PICKUP prediction),
    /// the hotbar row the store's own mirror (the HUD syncs on every
    /// mutation), and the hit boxes the 26.2 layout pins.
    #[test]
    fn the_inventory_click_walks_the_pickup_law() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        // the panel origin the render lays out first (the render-then-hit
        // pattern) — a 640x360 gui the geometry test pins
        app.inv_panel = inventory_panel_origin(640, 360);
        assert_eq!(app.inv_panel, (232, 97));
        // the store: cobblestone x27 in the hotbar slot 0, oak x16 slot 1
        app.inventory.items[0] = (62, 27);
        app.inventory.items[1] = (63, 16);
        app.hotbar_slots = app.inventory.hotbar();
        // THE PICKUP: the left press on the slot takes the whole stack
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 0);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(app.inventory.items[0], (0, 0), "the slot emptied");
        assert_eq!(app.inv_carried, (62, 27), "the cursor holds the stack");
        // THE PLACE: the same press on the empty main slot 9 puts it down
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 9);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(app.inventory.items[9], (62, 27), "the stack placed");
        assert_eq!(app.inv_carried, (0, 0), "the cursor empty");
        // the hotbar row synced (the store's own mirror)
        assert_eq!(app.hotbar_slots[0], (0, 0));
        // THE MERGE: pick the cobblestone up, drop it on oak — the swap
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 9);
        app.on_press(ox + 8, oy + 8);
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 1);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(app.inventory.items[1], (62, 27), "the swap landed");
        assert_eq!(app.inv_carried, (63, 16), "the oak rides the cursor");
        // the between-slots press INSIDE the panel does nothing (the
        // vanilla's own silence — only the OUTSIDE press throws, the
        // drop-outside lane's own tests speak)
        app.on_press(app.inv_panel.0 + 90, app.inv_panel.1 + 10);
        assert_eq!(app.inv_carried, (63, 16), "the carried untouched");
    }

    /// THE DROP-OUTSIDE LANE (the 26.2 AbstractContainerScreen's own
    /// hasClickedOutside walk + the doClick THROW's slot -999): the LEFT
    /// press outside the panel drops the WHOLE carried stack — the carry
    /// empties, one ItemDrop spawns at the eye minus the
    /// 0.30000001192092896 lift with the 40-tick pickup delay and the
    /// AIMED look throw (the 2-arg drop's own iconst_0 pins
    /// dropAround=FALSE — the boolean rides the includeThrower slot, the
    /// look-direction impulse the createItemStackToDrop else arm speaks)
    /// — and the container STAYS OPEN.
    #[test]
    fn the_outside_left_press_throws_the_whole_carried() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.inventory.items[0] = (62, 27);
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 0);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(app.inv_carried, (62, 27), "the stack rides the cursor");
        let drops_before = app.drops.len();
        // the OUTSIDE press (the 4,4 corner hasClickedOutside answers true)
        app.on_press(4, 4);
        assert_eq!(app.inv_carried, (0, 0), "the cursor emptied");
        assert_eq!(app.drops.len(), drops_before + 1, "one drop spawned");
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, 62);
        assert_eq!(d.count, 27, "the WHOLE stack thrown");
        assert_eq!(d.pickup_delay, 40, "the throw's own delay");
        let b = app.body.as_ref().unwrap();
        assert_eq!(d.x, b.x, "the body's x");
        assert_eq!(d.z, b.z, "the body's z");
        assert_eq!(
            d.y,
            b.y + b.eye_height() - 0.30000001192092896,
            "the eye minus the 0.30000001192092896 lift"
        );
        // the AIMED branch's own folds (seed 3's draw chain: the ctor's
        // bob seed, then f12 = nextFloat*6.2831855, f13 = 0.02*nextFloat,
        // the vy jitter pair r1/r2 — the look-direction law at the spawn
        // angles: the forward 0.3 fold minus the sin(pitch) share, the
        // 0.1 base lift, the ±0.05 jitter band, the cos/sin(f12)·f13
        // bob-cosine scatter ±0.02 wide — the spawn's own yaw speaks the
        // +X axis, the horizontal SPEED the axis-free pin)
        let speed = (d.vx * d.vx + d.vz * d.vz).sqrt();
        assert!(
            (speed - 0.3).abs() <= 0.03,
            "the look-direction 0.3 fold (speed={speed})"
        );
        assert!(
            d.vy > 0.05 && d.vy < 0.15,
            "the 0.1 base lift within the ±0.05 jitter band (vy={vy})",
            vy = d.vy
        );
        // the container STAYS OPEN (only the close keys close it)
        assert_eq!(app.screen, ScreenKind::Inventory);
        // and the store untouched (the throw rides the CURSOR, not the slots)
        assert_eq!(app.inventory.items[0], (0, 0));
    }

    /// THE DROP-OUTSIDE'S RIGHT PRESS (the doClick THROW's split(1)
    /// arm): ONE item flies, the carry decrements — twice for the count.
    #[test]
    fn the_outside_right_press_throws_one() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.inventory.items[0] = (63, 5);
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 0);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(app.inv_carried, (63, 5), "the stack rides");
        let drops_before = app.drops.len();
        app.on_right_press(4, 4);
        assert_eq!(app.inv_carried, (63, 4), "one split off");
        assert_eq!(app.drops.len(), drops_before + 1);
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, 63);
        assert_eq!(d.count, 1, "ONE item");
        assert_eq!(d.pickup_delay, 40);
        // the second press throws the next one
        app.on_right_press(4, 4);
        assert_eq!(app.inv_carried, (63, 3), "one more gone");
        assert_eq!(app.drops.len(), drops_before + 2);
        assert_eq!(app.drops.last().unwrap().count, 1);
        // the container stays open
        assert_eq!(app.screen, ScreenKind::Inventory);
    }

    /// THE DROP-OUTSIDE'S EMPTY-CURSOR SILENCE (the doClick THROW's own
    /// isEmpty guard): a press outside with nothing carried spawns
    /// nothing and leaves the screen whole.
    #[test]
    fn the_empty_cursor_outside_press_is_silence() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.inventory.items[0] = (62, 27);
        let drops_before = app.drops.len();
        app.on_press(4, 4);
        assert_eq!(app.drops.len(), drops_before, "no drop spawned");
        assert_eq!(app.inv_carried, (0, 0), "the cursor stayed empty");
        assert_eq!(app.screen, ScreenKind::Inventory, "the screen stays");
        // and the right press keeps the same silence
        app.on_right_press(4, 4);
        assert_eq!(app.drops.len(), drops_before, "still no drop");
    }

    /// THE Q-DROP LANE (the handleKeybinds keyDrop walk — the plain Q):
    /// the selected slot's ONE item flies the AIMED look throw, the slot
    /// decrements, the MAIN_HAND swing fires, the HUD hotbar syncs.
    #[test]
    fn the_q_key_throws_one_from_the_selected_slot() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.inventory.items[app.selected_hotbar] = (62, 7);
        let drops_before = app.drops.len();
        app.on_drop_key(false);
        // removeFromSelected(false): exactly ONE off
        assert_eq!(
            app.inventory.items[app.selected_hotbar],
            (62, 6),
            "one item gone from the selected slot"
        );
        assert_eq!(app.drops.len(), drops_before + 1, "one drop spawned");
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, 62);
        assert_eq!(d.count, 1, "ONE item");
        assert_eq!(d.pickup_delay, 40, "the throw's own delay");
        let b = app.body.as_ref().unwrap();
        assert_eq!(d.x, b.x, "the body's x");
        assert_eq!(d.z, b.z, "the body's z");
        assert_eq!(
            d.y,
            b.y + b.eye_height() - 0.30000001192092896,
            "the eye minus the 0.30000001192092896 lift"
        );
        // the AIMED look throw's own shape: the forward 0.3 fold (the
        // spawn's yaw/pitch speak the axis), the 0.1 base lift within
        // the ±0.05 jitter band, the bob-cosine scatter ±0.02 wide
        let speed = (d.vx * d.vx + d.vz * d.vz).sqrt();
        assert!(
            (speed - 0.3).abs() <= 0.03,
            "the horizontal speed the 0.3 fold speaks (speed={speed})"
        );
        assert!(
            d.vy > 0.05 && d.vy < 0.15,
            "the 0.1 base lift within the ±0.05 jitter band (vy={vy})",
            vy = d.vy
        );
        // the success arm's own swing (LivingEntity.swing MAIN_HAND)
        assert!(app.swing.swinging, "the swing fired");
        // and the HUD hotbar row synced (the store's own mirror)
        assert_eq!(app.hotbar_slots[app.selected_hotbar], (62, 6), "the HUD synced");
    }

    /// THE CTRL+Q FORM (LocalPlayer.drop's wholeStack boolean — the
    /// hasControlDown the keyDrop lane speaks): the WHOLE selected stack
    /// flies (removeFromSelected's removeItem(selected, getCount())
    /// arm), the slot empties.
    #[test]
    fn the_ctrl_q_throws_the_whole_stack() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.inventory.items[app.selected_hotbar] = (63, 12);
        let drops_before = app.drops.len();
        app.on_drop_key(true);
        assert_eq!(
            app.inventory.items[app.selected_hotbar],
            (0, 0),
            "the slot emptied"
        );
        assert_eq!(app.drops.len(), drops_before + 1, "one drop spawned");
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, 63);
        assert_eq!(d.count, 12, "the WHOLE stack");
        assert_eq!(d.pickup_delay, 40);
        assert!(app.swing.swinging, "the swing fired");
    }

    /// THE EMPTY SLOT'S SILENCE (removeFromSelected's own EMPTY law —
    /// drop returns false): no entity, no swing, no draw burned.
    #[test]
    fn the_empty_selected_slot_q_is_silence() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        let drops_before = app.drops.len();
        app.on_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "no drop spawned");
        assert!(!app.swing.swinging, "no swing — drop returned false");
        // the Ctrl form keeps the same silence
        app.on_drop_key(true);
        assert_eq!(app.drops.len(), drops_before, "still no drop");
        assert!(!app.swing.swinging, "still no swing");
    }

    /// THE Q KEY'S OWN GATE (the handleKeybinds overlay==null &&
    /// screen==null law): the keybinds the OPEN SCREEN never passes —
    /// the inventory-open Q is silence — and the wire session refuses
    /// honestly (the store the server owns, the DROP_ITEM action packet
    /// lane the follow-up names).
    #[test]
    fn the_q_key_refuses_the_screens_and_the_wire() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.inventory.items[app.selected_hotbar] = (62, 7);
        // the inventory OPEN — the screen != World the gate refuses
        app.open_inventory();
        let drops_before = app.drops.len();
        app.on_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the screen gate holds");
        assert_eq!(app.inventory.items[app.selected_hotbar], (62, 7), "the store whole");
        // the PAUSE — the vanilla's own freeze lane
        app.close_inventory();
        app.paused = true;
        app.on_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the pause freeze holds");
        // the WIRE session — the store the server owns
        app.paused = false;
        app.world_is_network = true;
        app.on_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the wire refusal holds");
        assert_eq!(app.inventory.items[app.selected_hotbar], (62, 7), "the wire store whole");
    }

    /// THE MIDDLE-CLICK PICK (the hotbar hit's own law — tryPickItem's
    /// `isHotbarSlot(i)` arm): the block the downward crosshair speaks,
    /// its item found IN the hotbar row — the setSelectedSlot walk
    /// re-points the selection, the store's counts untouched, NO swing
    /// (the pick chain never names one), NO drop, the HUD hotbar row
    /// the always-tail syncs.
    #[test]
    fn the_middle_click_picks_the_hotbar_block() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.body.as_mut().unwrap().pitch = 80.0; // the ground speaks — the hit guaranteed
        let hit = app
            .clip_crosshair()
            .expect("the downward aim hits the terrain");
        let kind = app
            .active_world()
            .map(|w| w.get(hit.pos.0, hit.pos.1, hit.pos.2))
            .expect("the offline world stands");
        assert_ne!(kind, crate::world::AIR, "the hit cell solid");
        let item = mc_registry::item_id_by_name(crate::world::NAME_OF[kind as usize])
            .expect("the terrain block carries its item");
        app.inventory.items[3] = (item, 5);
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 3, "the hotbar hit selected");
        assert_eq!(app.inventory.items[3], (item, 5), "the store untouched");
        assert!(!app.swing.swinging, "the pick chain never swings");
        assert!(app.drops.is_empty(), "no drop the pick never names");
        assert_eq!(app.hotbar_slots[3], (item, 5), "the HUD synced");
    }

    /// THE MAIN-INVENTORY HIT (the pickSlot walk the shared helper
    /// speaks): the item ONLY in the main grid — the suitable re-point
    /// first (the hand EMPTY answers the scan's first free slot, the
    /// selected itself), then the swap brings the item INTO the hand,
    /// the displaced empty rides back to the main grid.
    #[test]
    fn the_middle_click_swaps_the_main_inventory_match_into_the_hand() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.body.as_mut().unwrap().pitch = 80.0; // the vanilla positive-down degrees
        let hit = app.clip_crosshair().expect("the downward aim hits");
        let kind = app
            .active_world()
            .map(|w| w.get(hit.pos.0, hit.pos.1, hit.pos.2))
            .expect("the offline world stands");
        let item = mc_registry::item_id_by_name(crate::world::NAME_OF[kind as usize])
            .expect("the terrain block carries its item");
        app.inventory.items[9] = (item, 2); // the main grid ONLY — the hotbar clean
        app.on_pick_block(false);
        assert_eq!(
            app.selected_hotbar, 0,
            "the hand slot the suitable answer (the first free scanned)"
        );
        assert_eq!(app.inventory.items[0], (item, 2), "the item IN the hand");
        assert_eq!(app.inventory.items[9], (0, 0), "the main slot emptied");
        assert_eq!(app.hotbar_slots[0], (item, 2), "the HUD synced");
    }

    /// THE SUITABLE RE-POINT'S OWN LAW (getSuitableHotbarSlot code 91):
    /// the hand FULL and a free hotbar slot ahead — the scan
    /// `(selected + i) % 9` finds the FREE slot, the swap lands the
    /// item THERE, the selection follows it, the hand's own stack
    /// stays put (the displaced empty rides back to the main grid).
    #[test]
    fn the_middle_click_lands_in_the_first_free_hotbar_slot() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.body.as_mut().unwrap().pitch = 80.0; // the vanilla positive-down degrees
        let hit = app.clip_crosshair().expect("the downward aim hits");
        let kind = app
            .active_world()
            .map(|w| w.get(hit.pos.0, hit.pos.1, hit.pos.2))
            .expect("the offline world stands");
        let item = mc_registry::item_id_by_name(crate::world::NAME_OF[kind as usize])
            .expect("the terrain block carries its item");
        app.inventory.items[0] = (62, 7); // the hand full — the scan moves on
        app.inventory.items[9] = (item, 2);
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 1, "the scan's first free slot");
        assert_eq!(app.inventory.items[1], (item, 2), "the item lands there");
        assert_eq!(app.inventory.items[0], (62, 7), "the hand untouched");
        assert_eq!(app.inventory.items[9], (0, 0), "the displaced empty rides back");
        assert_eq!(app.hotbar_slots[1], (item, 2), "the HUD synced");
    }

    /// THE MIDDLE CLICK'S OWN SILENCES (the survival law's gates): the
    /// item NOWHERE in the store (the -1 the findSlotMatchingItem scan
    /// speaks — the creative addAndPickItem the hasInfiniteMaterials
    /// gate holds), the MISS (the sky the clip refuses), the death
    /// modal, the OPEN SCREEN and the pause (the handleKeybinds gate),
    /// the wire session (the store the server owns). Every arm leaves
    /// the selection and the store whole.
    #[test]
    fn the_middle_click_misses_silently() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.body.as_mut().unwrap().pitch = 80.0; // the vanilla positive-down degrees
        // the picked item NOWHERE in the 36 slots: the -1 silence
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 0, "the -1 never moved the selection");
        // the MISS: the sky the clip refuses
        app.body.as_mut().unwrap().pitch = -80.0; // the vanilla negative-up degrees
        assert!(app.clip_crosshair().is_none(), "the upward aim misses");
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 0, "the MISS never moved the selection");
        // the death modal
        app.body.as_mut().unwrap().pitch = 80.0; // the vanilla positive-down degrees
        app.inventory.items[3] = (62, 7); // a WRONG item — the store's own witness
        app.dead = true;
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 0, "the death gate holds");
        app.dead = false;
        // the OPEN SCREEN — the handleKeybinds gate refuses
        app.open_inventory();
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 0, "the screen gate holds");
        app.close_inventory();
        // the PAUSE — the vanilla's own freeze lane
        app.paused = true;
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 0, "the pause freeze holds");
        app.paused = false;
        // the WIRE session — the store the server owns
        app.world_is_network = true;
        app.on_pick_block(false);
        assert_eq!(app.selected_hotbar, 0, "the wire refusal holds");
        assert_eq!(app.inventory.items[3], (62, 7), "the store whole throughout");
    }

    /// THE 2x2 CRAFT GRID — the log's own loop (the survival chain the
    /// real game's muscle memory rides): the store's log rides the
    /// carried into a craft cell (the predict_pickup walk), the
    /// recompute law speaks the shapeless fast path (oak_log -> 4
    /// oak_planks), and the result slot's take rides the onTake walk —
    /// the whole result, the per-cell decrement, the recompute FIRING
    /// AGAIN while the logs speak (the further takes the real game
    /// clicks), the spent grid the EMPTY verdict keeps.
    #[test]
    fn the_craft_grid_turns_a_log_into_four_planks() {
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // the store's log into the hand, then INTO the craft cell 0
        // (panel (232, 97): store 5 at (330, 239), cell 0 at (330, 115)
        // — the 16x16 hit rects at the +1 inset, the result at (386,
        // 125); the clicks ride the on_press routing the store lane
        // shares)
        app.inventory.items[5] = (log, 3);
        app.on_press(338, 246);
        assert_eq!(app.inv_carried, (log, 3), "the log in the hand");
        app.on_press(338, 123);
        assert_eq!(app.craft_grid[0], (log, 3), "the cell holds the stack");
        assert_eq!(app.inv_carried, (0, 0), "the hand emptied");
        // THE RECOMPUTE (InventoryMenu.slotsChanged's own ask — the
        // getRecipeFor verdict the result slot keeps)
        assert_eq!(app.craft_result, (planks, 4), "the shapeless fast path");
        // THE TAKE — the whole result, the onTake's per-cell decrement,
        // the recompute firing again while the logs speak
        app.on_press(394, 133);
        assert_eq!(app.inv_carried, (planks, 4), "the whole result taken");
        assert_eq!(app.craft_grid[0], (log, 2), "one log off the cell");
        assert_eq!(app.craft_result, (planks, 4), "the recipe fires AGAIN");
        app.on_press(394, 133);
        assert_eq!(app.inv_carried, (planks, 8), "the second take merged");
        app.on_press(394, 133);
        assert_eq!(app.inv_carried, (planks, 12), "the third take");
        assert_eq!(app.craft_grid[0], (0, 0), "the cell spent");
        assert_eq!(app.craft_result, (0, 0), "the empty grid's EMPTY verdict");
        assert_eq!(app.inventory.items[5], (0, 0), "the store slot still empty");
    }

    /// THE ARMOR COLUMN (the 26.2 ArmorSlot's own mayPlace law — the
    /// isEquippableInSlot verdict the EQUIPPABLE component folds to,
    /// the slot max 1, the matching piece's swap the doClick arm
    /// speaks): the matching piece PLACES, the wrong piece's slot
    /// refuses (the stack stays on the cursor), the same-item full
    /// slot the silence keeps, the different matching piece SWAPS.
    /// The panel geometry: the armor column at (240, 105 + k * 18),
    /// the head center (248, 113), the chest center (248, 131).
    #[test]
    fn the_armor_slots_take_the_matching_piece_and_refuse_the_rest() {
        let helmet = mc_registry::item_id_by_name("iron_helmet").unwrap();
        let _chest = mc_registry::item_id_by_name("iron_chestplate").unwrap();
        let diamond = mc_registry::item_id_by_name("diamond_helmet").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // THE MATCHING PIECE PLACES (the head slot takes the helmet)
        app.inv_carried = (helmet, 1);
        app.on_press(248, 113);
        assert_eq!(app.inventory.armor[0], (helmet, 1), "the head wears it");
        assert_eq!(app.inv_carried, (0, 0), "the cursor emptied");
        // THE PICKUP (the empty cursor takes the piece back)
        app.on_press(248, 113);
        assert_eq!(app.inventory.armor[0], (0, 0), "the head bare");
        assert_eq!(app.inv_carried, (helmet, 1), "the piece in the hand");
        // THE WRONG PIECE'S SLOT REFUSES (the chest slot keeps its
        // gate — the helmet is not a chestplate)
        app.on_press(248, 131);
        assert_eq!(app.inventory.armor[1], (0, 0), "the chest still bare");
        assert_eq!(app.inv_carried, (helmet, 1), "the helmet stays held");
        // THE NON-ARMOR ITEM THE MAINHAND VERDICT REFUSES
        app.inv_carried = (planks, 12);
        app.on_press(248, 131);
        assert_eq!(app.inventory.armor[1], (0, 0), "the planks refused");
        assert_eq!(app.inv_carried, (planks, 12), "the planks stay held");
        // THE HEAD WORN AGAIN (the held helmet rides back — the swap
        // needs the slot SPEAKING)
        app.inv_carried = (helmet, 1);
        app.on_press(248, 113);
        assert_eq!(app.inventory.armor[0], (helmet, 1), "the head re-worn");
        assert_eq!(app.inv_carried, (0, 0), "the hand empty again");
        // THE SWAP (the different matching piece trades places — the
        // doClick mayPlace-true arm the result slot never speaks)
        app.inv_carried = (diamond, 1);
        app.on_press(248, 113);
        assert_eq!(app.inventory.armor[0], (diamond, 1), "the head re-wears");
        assert_eq!(app.inv_carried, (helmet, 1), "the iron rides the hand");
    }

    /// THE QUICK-MOVE ARMOR WALK (the quickMoveStack's own arm order —
    /// the bytecode 135 armor arm fires BEFORE the section routing and
    /// ENDS the walk when it moves): the store row's helmet lands in
    /// the EMPTY head slot (the hotbar routing never speaks), the
    /// occupied head sends the next helmet down the hotbar lane, the
    /// carved pumpkin the HEAD family keeps. The store 9 hit center
    /// (248, 189), store 10 (266, 189).
    #[test]
    fn the_shift_click_sends_the_store_row_helmet_to_the_empty_head_slot() {
        let helmet = mc_registry::item_id_by_name("iron_helmet").unwrap();
        let pumpkin = mc_registry::item_id_by_name("carved_pumpkin").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // THE ARMOR ARM ENDS THE WALK (the head empty — the whole
        // piece moves, the remainder stays, no hotbar routing)
        app.inventory.items[9] = (helmet, 1);
        app.shift_down = true;
        app.on_press(248, 189);
        app.shift_down = false;
        assert_eq!(app.inventory.armor[0], (helmet, 1), "the head took it");
        assert_eq!(app.inventory.items[9], (0, 0), "the source emptied");
        assert_eq!(app.inventory.items[0], (0, 0), "the hotbar untouched");
        // THE OCCUPIED HEAD SENDS IT DOWN THE SECTION LANE (the hotbar
        // rows the main-row source feeds — store 10's pumpkin is the
        // HEAD family too, but the head is full: the FIRST hotbar slot
        // takes it)
        app.inventory.items[10] = (pumpkin, 1);
        app.shift_down = true;
        app.on_press(266, 189);
        app.shift_down = false;
        assert_eq!(app.inventory.armor[0], (helmet, 1), "the head kept its piece");
        assert_eq!(app.inventory.items[10], (0, 0), "the source emptied");
        assert_eq!(app.inventory.items[0], (pumpkin, 1), "the hotbar took the rest");
    }

    /// THE OFFHAND SLOT (the anonymous slot 45's own law — mayPlace
    /// the base slot's unconditional TRUE keeps, the max the item's
    /// own 64 speaks): ANY stack places, the pickup takes it back,
    /// and the ADD walk's container-40 arm the getSlotWithRemainingSpace
    /// bytecode 21-37 keeps speaks — the selected stack full, the
    /// store's free slots gone, the offhand's same-item stack the
    /// remaining-space verdict takes the rest.
    #[test]
    fn the_offhand_takes_any_stack_and_the_pickup_lands_there() {
        let torch = mc_registry::item_id_by_name("torch").unwrap();
        let cobble = mc_registry::item_id_by_name("cobblestone").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // THE PLACE (any stack rides the offhand)
        app.inv_carried = (torch, 10);
        app.on_press(317, 167);
        assert_eq!(app.inventory.offhand[0], (torch, 10), "the offhand took it");
        assert_eq!(app.inv_carried, (0, 0), "the cursor emptied");
        // THE PICKUP (the whole stack back)
        app.on_press(317, 167);
        assert_eq!(app.inventory.offhand[0], (0, 0), "the offhand bare");
        assert_eq!(app.inv_carried, (torch, 10), "the stack in the hand");
        // THE ADD WALK'S OFFHAND LANE (the selected full, the main
        // rows full with the OTHER item, the offhand's 30 the
        // container-40 verdict fills)
        app.inventory.items[0] = (torch, 64);
        app.inventory.offhand[0] = (torch, 30);
        for it in app.inventory.items.iter_mut().skip(9) {
            *it = (cobble, 64);
        }
        let leftover = app.inventory.add(0, torch, 5);
        assert_eq!(leftover, 0, "the offhand took all five");
        assert_eq!(app.inventory.offhand[0], (torch, 35), "the container-40 fill");
        assert_eq!(app.inventory.items[0], (torch, 64), "the selected untouched");
    }

    /// THE WORN PIECE'S SHIFT-CLICK (the quickMoveStack's own
    /// fallthrough for the menu 5..8 sources — the final `[9, 45)`
    /// FORWARD move the section arms never match): the piece walks to
    /// the store, the MAIN rows first (the forward order the menu's
    /// own ascending walk keeps), the hotbar after when the main rows
    /// speak no home. The chest hit center (248, 131).
    #[test]
    fn the_shift_click_moves_the_worn_piece_to_the_store() {
        let chest = mc_registry::item_id_by_name("iron_chestplate").unwrap();
        let helmet = mc_registry::item_id_by_name("iron_helmet").unwrap();
        let cobble = mc_registry::item_id_by_name("cobblestone").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // THE MAIN ROWS FIRST (the forward [9, 45) walk — store 9 the
        // first empty the ascending order answers)
        app.inventory.armor[1] = (chest, 1);
        app.shift_down = true;
        app.on_press(248, 131);
        app.shift_down = false;
        assert_eq!(app.inventory.items[9], (chest, 1), "the main row took it");
        assert_eq!(app.inventory.armor[1], (0, 0), "the chest bare");
        // THE MAIN ROWS FULL — THE HOTBAR AFTER (the forward walk's
        // own tail: the hotbar 0..8 the range's last arm answers)
        app.inventory.armor[0] = (helmet, 1);
        for it in app.inventory.items.iter_mut().skip(9) {
            *it = (cobble, 64);
        }
        app.shift_down = true;
        app.on_press(248, 113);
        app.shift_down = false;
        assert_eq!(app.inventory.items[0], (helmet, 1), "the hotbar took it");
        assert_eq!(app.inventory.armor[0], (0, 0), "the head bare");
        assert_eq!(app.hotbar_slots[0], (helmet, 1), "the HUD row synced");
    }

    /// THE Q-OVER-THE-EQUIPMENT LANE (the getHoveredSlot walk's own
    /// completeness — the armor column and the offhand the menu's
    /// slot list keeps): the hovered piece the doClick THROW speaks,
    /// the carried stack's own gate the silence keeps.
    #[test]
    fn the_drop_key_throws_the_hovered_piece() {
        let helmet = mc_registry::item_id_by_name("iron_helmet").unwrap();
        let torch = mc_registry::item_id_by_name("torch").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // THE PIECE THROWS (one off — the single piece the whole-stack
        // law answers the same; the safeTake walk leaves the count-0
        // pair the store's own empty sentinel keeps)
        app.inventory.armor[0] = (helmet, 1);
        app.mouse_pos = Some((248, 113));
        app.on_inventory_drop_key(false);
        assert_eq!(app.inventory.armor[0], (helmet, 0), "the head bare");
        assert!(
            app.drops.iter().any(|d| d.item == helmet && d.count == 1),
            "the piece rides the aimed throw"
        );
        // THE CARRIED STACK'S GATE (the cursor full — the throw
        // refuses)
        app.inventory.offhand[0] = (torch, 3);
        app.inv_carried = (torch, 5);
        app.mouse_pos = Some((317, 167));
        app.on_inventory_drop_key(false);
        assert_eq!(app.inventory.offhand[0], (torch, 3), "the offhand kept it");
    }

    /// THE SHAPED SET (ShapedRecipePattern.matches's own law — the
    /// packed w/h equality, the cell-by-cell test, the tag law): the
    /// sticks' 1x2 column the pack law folds to w=1 in EITHER column
    /// (the bounding box the ofPositioned walk keeps), the horizontal
    /// pair the w/h equality refuses, the mixed-planks table the
    /// independent tag cells craft, the torch's order the pattern
    /// speaks, the sandstone the 2x2 keeps, the spruce singles the
    /// shapeless fast path answers, the lone plank no recipe names.
    #[test]
    fn the_craft_grid_speaks_the_shaped_set() {
        let oak = mc_registry::item_id_by_name("oak_planks").unwrap();
        let spruce = mc_registry::item_id_by_name("spruce_planks").unwrap();
        let birch = mc_registry::item_id_by_name("birch_planks").unwrap();
        let stick = mc_registry::item_id_by_name("stick").unwrap();
        let coal = mc_registry::item_id_by_name("coal").unwrap();
        let torch = mc_registry::item_id_by_name("torch").unwrap();
        let table = mc_registry::item_id_by_name("crafting_table").unwrap();
        let sand = mc_registry::item_id_by_name("sand").unwrap();
        let sandstone = mc_registry::item_id_by_name("sandstone").unwrap();
        let spruce_log = mc_registry::item_id_by_name("spruce_log").unwrap();
        // THE STICKS — the RIGHT column (cells 1 + 3), the pack law's
        // bounding box answers the same as the left
        let cells = [(oak, 1), (0, 0), (oak, 1), (0, 0)];
        assert_eq!(craft_result_for(&cells), (stick, 4), "the right column");
        let cells = [(oak, 1), (0, 0), (0, 0), (oak, 1)];
        assert_eq!(
            craft_result_for(&cells), (0, 0),
            "the diagonal's holes the pack keeps — no recipe names it"
        );
        let cells = [(oak, 1), (oak, 1), (0, 0), (0, 0)];
        assert_eq!(
            craft_result_for(&cells), (0, 0),
            "the horizontal pair the w/h equality refuses"
        );
        // THE MIXED-PLANKS TABLE (the tag each cell tests INDEPENDENTLY
        // — the oak+spruce+birch mix the real game crafts)
        let cells = [(oak, 1), (spruce, 2), (birch, 1), (oak, 3)];
        assert_eq!(craft_result_for(&cells), (table, 1), "the tag's own verdict");
        // THE TORCH — coal over stick, the order the pattern speaks
        let cells = [(coal, 1), (0, 0), (stick, 1), (0, 0)];
        assert_eq!(craft_result_for(&cells), (torch, 4), "the [C, S] column");
        let cells = [(stick, 1), (0, 0), (coal, 1), (0, 0)];
        assert_eq!(craft_result_for(&cells), (0, 0), "the stick-under-coal refused");
        // THE SANDSTONE — the 2x2
        let cells = [(sand, 1); 4];
        assert_eq!(craft_result_for(&cells), (sandstone, 1), "the 2x2 sand");
        // THE SPRUCE SINGLES (the shapeless fast path per wood)
        let cells = [(spruce_log, 1), (0, 0), (0, 0), (0, 0)];
        assert_eq!(craft_result_for(&cells), (spruce, 4), "the spruce pair");
        // THE LONE PLANK — no recipe names it
        let cells = [(oak, 1), (0, 0), (0, 0), (0, 0)];
        assert_eq!(craft_result_for(&cells), (0, 0), "the single plank's silence");
    }

    /// THE TAKE'S OWN GATES (the doClick PICKUP walk over the
    /// mayPlace-false result slot): the same-item merge the 1020 arm
    /// keeps (the carried's own space caps the take), the FULL carried
    /// refuses (the getMaxStackSize if_icmpgt), the different item's
    /// silence (the isSameItemSameComponents ifeq — no swap rides a
    /// mayPlace-false slot), and the secondary take's half rounded up
    /// (the (count+1)/2 the arm speaks).
    #[test]
    fn the_craft_result_take_gates_and_the_secondary_half() {
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let stick = mc_registry::item_id_by_name("stick").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // one cell, two logs — the two crafts (the shapeless law's own
        // count: TWO cells of logs the ingredientCount equality
        // REFUSES — the one-ingredient recipe speaks only the
        // one-cell input, the multi-count stack the crafts repeat)
        app.craft_grid[0] = (log, 2);
        app.craft_grid[2] = (log, 2);
        app.refresh_craft_result();
        assert_eq!(app.craft_result, (0, 0), "two cells the count law refuses");
        app.craft_grid[2] = (0, 0);
        app.refresh_craft_result();
        assert_eq!(app.craft_result, (planks, 4), "the one-cell input speaks");
        // THE MERGE ARM — the carried's space (2) caps the take
        app.inv_carried = (planks, 62);
        app.on_press(394, 133);
        assert_eq!(app.inv_carried, (planks, 64), "the space caps the take");
        assert_eq!(app.craft_result, (planks, 4), "the craft still speaks");
        // THE FULL CARRIED — the if_icmpgt arm's silence
        app.on_press(394, 133);
        assert_eq!(app.inv_carried, (planks, 64), "the full carried refuses");
        assert_eq!(app.craft_result, (planks, 4), "no take, no decrement");
        // THE DIFFERENT ITEM — the ifeq arm's silence
        app.inv_carried = (stick, 10);
        app.on_press(394, 133);
        assert_eq!(app.inv_carried, (stick, 10), "no swap on the result slot");
        assert_eq!(app.craft_result, (planks, 4), "the result untouched");
        // THE SECONDARY TAKE — the half rounded up, ONE craft's
        // decrement per take, the last craft the spent cell gives
        app.inv_carried = (0, 0);
        app.on_right_press(394, 133);
        assert_eq!(app.inv_carried, (planks, 2), "the (count+1)/2 arm");
        assert_eq!(app.craft_grid[0], (0, 0), "the last craft spent");
        assert_eq!(app.craft_result, (0, 0), "the spent grid's EMPTY verdict");
    }

    /// THE CRAFT CELLS' OWN PICKUP LANES (the doClick PICKUP over the
    /// mayPlace-default cells — the TransientCraftingContainer the
    /// place walk accepts): the right press's ceiling-half split, the
    /// one-by-one place, the merge-back, the shift-click's silence
    /// (the quick-move-into-craft lane rides later), and the WIRE
    /// session's refusal (the store the server owns — the whole
    /// inventory click lane's own gate the craft region rides).
    #[test]
    fn the_craft_cells_keep_the_pickup_lanes_and_the_refusals() {
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // the RIGHT press takes the ceiling half (4 -> 2 + 2)
        app.craft_grid[0] = (planks, 4);
        app.on_right_press(338, 123);
        assert_eq!(app.craft_grid[0], (planks, 2), "half stays");
        assert_eq!(app.inv_carried, (planks, 2), "the ceiling half taken");
        // the RIGHT press places ONE back
        app.on_right_press(338, 123);
        assert_eq!(app.craft_grid[0], (planks, 3), "one placed back");
        assert_eq!(app.inv_carried, (planks, 1), "the hand one lighter");
        // the LEFT press merges the hand's single back (the same-item
        // walk the store slots speak)
        app.on_press(338, 123);
        assert_eq!(app.craft_grid[0], (planks, 4), "the merge-back");
        assert_eq!(app.inv_carried, (0, 0), "the hand emptied");
        // the SHIFT-click's silence (the quick-move lane rides later)
        app.shift_down = true;
        app.inv_carried = (log, 1);
        app.on_press(338, 123);
        assert_eq!(app.craft_grid[0], (planks, 4), "the shift never moved it");
        assert_eq!(app.inv_carried, (log, 1), "the hand whole");
        app.shift_down = false;
        // the WIRE session — the store the server owns (the click
        // lane's own early return the craft region rides too)
        app.world_is_network = true;
        app.on_press(338, 123);
        assert_eq!(app.craft_grid[0], (planks, 4), "the wire refusal holds");
        assert_eq!(app.inv_carried, (log, 1), "the hand whole on the wire");
    }

    /// THE TABLE'S OWN KIND (the atlas RUNTIME_PALETTE's 37 index —
    /// the autopush-328 round): the world's vocabulary speaks the
    /// name, the placement arm's reverse lookup answers, the atlas
    /// row carries the four real tiles the vanilla cube model names
    /// (front/side/top + the oak_planks down face), the dig/drop/item
    /// lanes the registry's own tables serve.
    #[test]
    fn the_table_block_rides_the_world_kind() {
        let kind = crate::world::CRAFTING_TABLE;
        assert_eq!(
            crate::world::NAME_OF[kind as usize],
            "crafting_table",
            "the vocabulary's own name"
        );
        assert_eq!(
            crate::world::World::placeable_block("crafting_table"),
            Some(kind),
            "the placement's reverse lookup"
        );
        // the atlas row: the six faces all ride REAL tiles (the
        // textured path the goldens' own lane speaks)
        let row = mc_registry::generated::atlas::FACE_TILES[kind as usize];
        assert!(
            row.iter().all(|t| *t != mc_registry::generated::atlas::TILE_NONE),
            "the table's faces ride real tiles: {:?}",
            row
        );
        // the four distinct tiles the vanilla model names (front/
        // side/top + the oak_planks down face)
        let mut distinct = row.to_vec();
        distinct.sort();
        distinct.dedup();
        assert_eq!(distinct.len(), 4, "front/side/top/planks-down: {:?}", distinct);
        // the registry's own lanes: the dig row, the drop pools, the
        // item the pickup and the placement speak
        assert!(
            mc_registry::generated::block_dig::dig_row("crafting_table").is_some(),
            "the dig row the registry keeps"
        );
        assert!(
            mc_registry::generated::block_drops::drops("crafting_table").is_some(),
            "the drop pools the registry keeps"
        );
        assert!(mc_registry::item_id_by_name("crafting_table").is_some(), "the item rides");
        // THE MESH: the placed table's cube the full-cube path meshes,
        // the quads the table's own tiles carry
        let mut w = crate::world::World::new(2, 42);
        w.set(8, 20, 8, kind);
        let q = crate::mesher::mesh_world(&w, None);
        assert!(
            q.iter()
                .any(|quad| row.contains(&quad.tile)),
            "the table's faces meshed with the atlas tiles"
        );
    }

    /// THE TABLE'S OWN 3x3 RECIPE WALK (the shared packed matcher the
    /// jar's recipe JSONs speak — the bow's diagonal spine, the wooden
    /// tools' rows, the mirror arm the axe's handedness keeps): the
    /// bounding-box pack the CraftingInput.ofPositioned law keeps, the
    /// w/h equality the shaped walk refuses on, the EMPTY verdict the
    /// wrong arrangements speak.
    #[test]
    fn the_table_crafts_the_bow_and_the_wooden_tools() {
        let id = |name: &str| mc_registry::item_id_by_name(name).unwrap();
        let (stick, string) = (id("stick"), id("string"));
        let (oak, spruce, birch) = (id("oak_planks"), id("spruce_planks"), id("birch_planks"));
        let zero = (0, 0);
        // THE BOW ([" #X", "# X", " #X"] — the sticks' diagonal spine,
        // the string column the right edge keeps)
        let bow = id("bow");
        let cells: [(i32, i32); 9] = [
            zero, (stick, 1), (string, 1),
            (stick, 1), zero, (string, 1),
            zero, (stick, 1), (string, 1),
        ];
        assert_eq!(craft_result_for_table(&cells), (bow, 1), "the jar's own row");
        // the mirrored arrangement (the string column LEFT) — the
        // MIRROR ARM answers (the bow's pattern the symmetrical flag
        // keeps false — the jar's own try-both-orientations walk the
        // mirrored rows serve)
        let mirrored: [(i32, i32); 9] = [
            (string, 1), (stick, 1), zero,
            (string, 1), zero, (stick, 1),
            (string, 1), (stick, 1), zero,
        ];
        assert_eq!(craft_result_for_table(&mirrored), (bow, 1), "the mirror arm answers");
        // THE WRONG STRING COUNT — the w/h equality's own refusal (the
        // two strings the ingredient count refuses)
        let cells: [(i32, i32); 9] = [
            zero, (stick, 1), (string, 1),
            (stick, 1), zero, zero,
            zero, (stick, 1), (string, 1),
        ];
        assert_eq!(craft_result_for_table(&cells), (0, 0), "the gap refuses");
        // THE WOODEN PICKAXE (["XXX", " # ", " # "])
        let pick = id("wooden_pickaxe");
        let cells: [(i32, i32); 9] = [
            (oak, 1), (spruce, 1), (birch, 1),
            zero, (stick, 1), zero,
            zero, (stick, 1), zero,
        ];
        assert_eq!(craft_result_for_table(&cells), (pick, 1), "the mixed planks the tag answers");
        // THE WOODEN AXE BOTH HANDEDNESS (["XX", "X#", " #"] + the
        // mirror arm the symmetrical flag keeps)
        let axe = id("wooden_axe");
        let cells: [(i32, i32); 9] = [
            (oak, 1), (oak, 1), zero,
            (oak, 1), (stick, 1), zero,
            zero, (stick, 1), zero,
        ];
        assert_eq!(craft_result_for_table(&cells), (axe, 1), "the jar's own row");
        let cells: [(i32, i32); 9] = [
            (oak, 1), (oak, 1), zero,
            (stick, 1), (oak, 1), zero,
            (stick, 1), zero, zero,
        ];
        assert_eq!(craft_result_for_table(&cells), (axe, 1), "the mirror arm answers");
        // THE SHOVEL + THE SWORD (the 1-wide columns)
        let cells: [(i32, i32); 9] = [
            (oak, 1), zero, zero,
            (stick, 1), zero, zero,
            (stick, 1), zero, zero,
        ];
        assert_eq!(craft_result_for_table(&cells), (id("wooden_shovel"), 1), "the shovel column");
        let cells: [(i32, i32); 9] = [
            (oak, 1), zero, zero,
            (oak, 1), zero, zero,
            (stick, 1), zero, zero,
        ];
        assert_eq!(craft_result_for_table(&cells), (id("wooden_sword"), 1), "the sword column");
        // THE SHIFTED COLUMN — the pack law the recipe's own position
        // answers (the shovel column in the MIDDLE cell rides home the
        // same verdict — the bounding box folds to the same input)
        let cells: [(i32, i32); 9] = [
            zero, (oak, 1), zero,
            zero, (stick, 1), zero,
            zero, (stick, 1), zero,
        ];
        assert_eq!(craft_result_for_table(&cells), (id("wooden_shovel"), 1), "the shifted column");
        // THE 2x2's OWN BOUND — the inventory grid can never fit the
        // 3-wide rows (the packed w/h equality the smaller grid
        // refuses): the full planks row + the stick column IS the
        // pickaxe in the table, but the 2x2's four cells hold at most
        // a 2x2 input — the pickaxe never speaks there
        let cells: [(i32, i32); 4] = [(oak, 1), (oak, 1), (stick, 1), (stick, 1)];
        assert_eq!(craft_result_for(&cells), (0, 0), "no 2x2 recipe names these");
    }

    /// THE TABLE SCREEN'S OWN LANES (the open's fresh grid, the cell
    /// clicks' place/take walks, the result's recompute, the close's
    /// clearContainer ride-home): the transient menu the vanilla use
    /// speaks per open, the contents the alive player's
    /// placeItemBackInInventory answers.
    #[test]
    fn the_table_screen_clicks_speak_the_grid_lanes() {
        let id = |name: &str| mc_registry::item_id_by_name(name).unwrap();
        let (planks, stick) = (id("oak_planks"), id("stick"));
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        // THE OPEN: the fresh grid, the Crafting screen
        app.open_crafting_table();
        assert_eq!(app.screen, ScreenKind::Crafting, "the menu opens");
        assert!(
            app.table_grid.iter().all(|c| c.1 == 0),
            "the transient menu's own fresh grid"
        );
        app.table_panel = inventory_panel_origin(640, 360);
        let (px, py) = inventory_panel_origin(640, 360);
        // THE CELL CLICKS place the carried whole (the predict_pickup
        // walk the store slots speak) and the recompute follows — the
        // sticks recipe ([P / P] the left column keeps)
        app.inv_carried = (planks, 6);
        app.on_press(px + 30 + 1 + 8, py + 17 + 1 + 8); // cell 0
        assert_eq!(app.table_grid[0], (planks, 6), "the whole stack places");
        assert_eq!(app.inv_carried, (0, 0), "the hand emptied");
        app.inv_carried = (planks, 6);
        app.on_press(px + 30 + 1 + 8, py + 17 + 18 + 1 + 8); // cell 3 (row 1)
        assert_eq!(app.table_grid[3], (planks, 6), "the second cell places");
        assert_eq!(app.table_result, (stick, 4), "the sticks recipe speaks");
        // THE RESULT TAKE (the mayPlace-false slot's own walk): the
        // carried receives, the cells one off, the recipe RE-SPEAKS
        let (rx, ry) = table_craft_origin(app.table_panel, 9);
        app.on_press(rx + 1 + 8, ry + 1 + 8);
        assert_eq!(app.inv_carried, (stick, 4), "the whole result taken");
        assert_eq!(app.table_grid[0], (planks, 5), "the cell one off");
        assert_eq!(app.table_result, (stick, 4), "the recipe re-speaks");
        // THE SECOND CRAFT the merge arm serves (the same-item carried
        // the carried's space caps — 4 + 4 = 8)
        app.on_press(rx + 1 + 8, ry + 1 + 8);
        assert_eq!(app.inv_carried, (stick, 8), "the merge arm answers");
        assert_eq!(app.table_grid[0], (planks, 4), "the cells keep spending");
        // THE CLOSE (the clearContainer walk): the grid's 8 planks and
        // the carried's 8 sticks ride home, the store keeps them
        app.close_crafting_table();
        assert_eq!(app.screen, ScreenKind::World, "the menu closes");
        assert_eq!(app.inv_carried, (0, 0), "the carried rode home");
        assert!(
            app.table_grid.iter().all(|c| c.1 == 0),
            "the grid emptied (the removeItemNoUpdate walk)"
        );
        let planks_in_store: i32 = app
            .inventory
            .items
            .iter()
            .filter(|(i, _)| *i == planks)
            .map(|(_, c)| c)
            .sum();
        let sticks_in_store: i32 = app
            .inventory
            .items
            .iter()
            .filter(|(i, _)| *i == stick)
            .map(|(_, c)| c)
            .sum();
        assert_eq!(planks_in_store, 8, "the grid contents rode home");
        assert_eq!(sticks_in_store, 8, "the carried rode home");
        assert_eq!(app.table_result, (0, 0), "the result slot's own reset");
        // THE E KEY'S OWN LANE (the toggle the container screen
        // answers): the reopened table the key closes back
        app.open_crafting_table();
        app.on_inventory_key();
        assert_eq!(app.screen, ScreenKind::World, "the E key closes the table");
        // THE ESCAPE'S OWN LANE mirrors (the open + the on_escape walk)
        app.open_crafting_table();
        app.on_escape();
        assert_eq!(app.screen, ScreenKind::World, "the Escape closes the table");
    }

    /// THE TABLE'S OWN USE LANE (javap 26.2 GameType.useItemOn — the
    /// block.use dispatch the item.useOn walk precedes): the
    /// non-sneaking right-press on the placed table the CONSUME
    /// verdict opens the 3x3 screen, the SNEAKING press the gate
    /// skips — the item lanes fall through and the held block PLACES.
    #[test]
    fn the_table_screen_opens_on_the_use_and_the_sneak_bypasses() {
        let mut app = App::new(3);
        app.enter_world();
        // NO BODY (the spawn's own box the placement's entity law
        // refuses — the placement cell the straight-down ray names IS
        // the standing cell): the bare world the vanilla's own
        // no-intersection guard keeps honest
        app.offline_held_updated(Some("item/dirt"));
        let size = app.offline_world.as_ref().unwrap().size_blocks();
        let c = size / 2;
        let top = app.spawn_y;
        // THE SNEAK BYPASS FIRST (the isShiftKeyDown gate the vanilla's
        // own arm keeps): the shift-down press the table-use walk
        // never arms — the held dirt the placement lane places on the
        // surface
        app.offline_camera_updated(crate::camera::Camera {
            pos: crate::math::Vec3::new(c as f32 + 0.5, top as f32 + 4.0, c as f32 + 0.5),
            yaw: 0.0,
            pitch: -std::f32::consts::FRAC_PI_2,
        });
        app.shift_down = true;
        assert!(app.on_right_press(0, 0), "the sneak placement consumed");
        assert_eq!(
            app.offline_world.as_ref().unwrap().get(c, top, c),
            crate::world::DIRT,
            "the dirt placed (the bypass spoke)"
        );
        assert_eq!(app.screen, ScreenKind::World, "no screen opened on the sneak");
        app.shift_down = false;
        // THE USE (the non-sneaking press on the table cell): the
        // interactive arm opens the 3x3 screen and CONSUMES the press
        app.offline_world
            .as_mut()
            .unwrap()
            .set(c, top, c, crate::world::CRAFTING_TABLE);
        assert!(app.on_right_press(0, 0), "the table's use consumes");
        assert_eq!(app.screen, ScreenKind::Crafting, "the 3x3 screen opened");
        assert_eq!(
            app.offline_world.as_ref().unwrap().get(c, top, c),
            crate::world::CRAFTING_TABLE,
            "the world cell untouched"
        );
        // THE ESCAPE back — the world screen stands
        app.on_escape();
        assert_eq!(app.screen, ScreenKind::World);
    }

    /// THE SHIFT-CLICK BATCH (the doClick QUICK_MOVE arm over the
    /// result slot — the quickMoveStack loop the while-same-item guard
    /// keeps): the whole log stack crafts in ONE press, the store the
    /// moveItemStackTo(stack, 9, 45, TRUE) walk fills — the merge pass
    /// over the whole range FIRST (the hotbar END-first the menu's own
    /// slot order speaks), the first-empty pass after — and the batch
    /// NEVER touches the carried stack (the quickMoveStack walk the
    /// carried ignores). The empty result the silence keeps, the wire
    /// session the lane's own early return.
    #[test]
    fn the_shift_click_crafts_the_whole_log_into_the_store() {
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // the EMPTY result — the shift's silence (no store move, no drop)
        app.shift_down = true;
        app.on_press(394, 133);
        assert!(app.drops.is_empty(), "the empty result never spoke");
        assert_eq!(app.inventory.items[8], (0, 0), "the store whole");
        // the stage: five logs in the cell, a partial plank stack in
        // the hotbar END (the merge-first order's own witness), a
        // carried stack the batch must never touch
        app.craft_grid[0] = (log, 5);
        app.refresh_craft_result();
        app.inventory.items[8] = (planks, 62);
        app.inv_carried = (log, 1);
        app.hotbar_slots = app.inventory.hotbar();
        // THE BATCH — one shift-click crafts the whole cell
        app.on_press(394, 133);
        // craft 1: the merge pass took 2 into store 8 (62 -> 64), the
        // first-empty pass landed the rest in store 7; crafts 2..5
        // merged into store 7 (the hotbar-END-first law)
        assert_eq!(app.inventory.items[8], (planks, 64), "the merge first");
        assert_eq!(app.inventory.items[7], (planks, 18), "the rest merged there");
        for s in (0..7).chain(9..36) {
            assert_eq!(app.inventory.items[s], (0, 0), "slot {s} untouched");
        }
        assert_eq!(app.craft_grid[0], (0, 0), "the cell spent");
        assert_eq!(app.craft_result, (0, 0), "the spent grid's EMPTY verdict");
        assert_eq!(app.inv_carried, (log, 1), "the carried never rode");
        assert!(app.drops.is_empty(), "nothing the store could not hold");
        assert_eq!(app.hotbar_slots[7], (planks, 18), "the HUD synced");
        assert_eq!(app.hotbar_slots[8], (planks, 64), "the HUD synced");
        // THE WIRE — the lane's own early return keeps the shift silent
        app.world_is_network = true;
        app.on_press(394, 133);
        assert_eq!(app.inventory.items[7], (planks, 18), "the wire refusal holds");
    }

    /// THE LEFTOVER DROP (the quickMoveStack index-0 tail — the 378-385
    /// bytecode): the stack part the store never holds rides
    /// `player.drop(stack, false)` — the AIMED throw the shared lane
    /// keeps — and the batch breaks on the nothing-moved EMPTY the
    /// NEXT iteration speaks (the recipe still matching, the store
    /// full, the loop the EMPTY verdict ends).
    #[test]
    fn the_shift_click_drops_the_leftover_when_the_store_cannot_hold() {
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // the store FULL of planks but ONE room in the hotbar end
        for s in 0..36 {
            app.inventory.items[s] = (planks, 64);
        }
        app.inventory.items[8] = (planks, 63);
        app.craft_grid[0] = (log, 2); // two crafts speak
        app.refresh_craft_result();
        // THE BATCH: craft 1 merges ONE into store 8 (63 -> 64), the
        // leftover 3 rides the aimed drop; craft 2 the nothing-moved
        // EMPTY breaks — the result still speaks, the cell holds one
        app.shift_down = true;
        app.on_press(394, 133);
        assert_eq!(app.inventory.items[8], (planks, 64), "the one room filled");
        assert_eq!(app.drops.len(), 1, "the leftover dropped");
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, planks, "the result's own item");
        assert_eq!(d.count, 3, "the store's leftover (4 - 1)");
        assert_eq!(d.pickup_delay, 40, "the aimed throw's own delay");
        assert_eq!(app.craft_grid[0], (log, 1), "ONE craft's decrement");
        assert_eq!(app.craft_result, (planks, 4), "the recipe still speaks");
        assert_eq!(app.hotbar_slots[8], (planks, 64), "the HUD synced");
    }

    /// THE INVENTORY'S OWN Q (the AbstractContainerScreen.keyPressed's
    /// keyDrop arm — the plain form): the HOVERED slot's ONE item flies
    /// the AIMED look throw, the slot decrements, NO swing (the
    /// keyPressed chain the success arm never names), the HUD hotbar
    /// row syncs, the container stays open.
    #[test]
    fn the_inventory_q_throws_one_from_the_hovered_slot() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // store 5 = the hotbar row's own rect (the slot origin walk):
        // panel (232, 97) -> slot 5 origin (330, 239), the cursor inside
        app.inventory.items[5] = (62, 7);
        app.mouse_pos = Some((336, 246));
        let drops_before = app.drops.len();
        app.on_inventory_drop_key(false);
        // safeTake(1, MAX): exactly ONE off the hovered slot
        assert_eq!(app.inventory.items[5], (62, 6), "one item gone");
        assert_eq!(app.drops.len(), drops_before + 1, "one drop spawned");
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, 62);
        assert_eq!(d.count, 1, "ONE item");
        assert_eq!(d.pickup_delay, 40, "the throw's own delay");
        let b = app.body.as_ref().unwrap();
        assert_eq!(d.x, b.x, "the body's x");
        assert_eq!(d.z, b.z, "the body's z");
        assert_eq!(
            d.y,
            b.y + b.eye_height() - 0.30000001192092896,
            "the eye minus the 0.30000001192092896 lift"
        );
        // the AIMED look throw's own shape (the createItemStackToDrop
        // folds — the 0.3 forward, the 0.1 lift within the jitter band)
        let speed = (d.vx * d.vx + d.vz * d.vz).sqrt();
        assert!(
            (speed - 0.3).abs() <= 0.03,
            "the horizontal speed the 0.3 fold speaks (speed={speed})"
        );
        assert!(
            d.vy > 0.05 && d.vy < 0.15,
            "the 0.1 base lift within the ±0.05 jitter band (vy={vy})",
            vy = d.vy
        );
        // the keyPressed chain names NO swing — the handleKeybinds
        // success arm the container walk never rides
        assert!(!app.swing.swinging, "no swing on the container's Q");
        // the HUD hotbar row synced (store 5 IS the hotbar row)
        assert_eq!(app.hotbar_slots[5], (62, 6), "the HUD synced");
        // the container stays open
        assert_eq!(app.screen, ScreenKind::Inventory, "the screen stays");
    }

    /// THE INVENTORY'S CTRL+Q (the keyPressed hasControlDown ? 1 : 0
    /// button int — the doClick's `count = button == 0 ? 1 :
    /// slot.getItem().getCount()` arm): the WHOLE hovered stack flies,
    /// the slot empties — and a MAIN-ROW slot the hotbar never
    /// contains answers too (the geometry walk beyond the hotbar row).
    #[test]
    fn the_inventory_ctrl_q_throws_the_whole_hovered_stack() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // store 12 = the main row's own rect: i = 3 -> panel-relative
        // (62, 84) -> absolute (294, 181), the cursor inside
        app.inventory.items[12] = (63, 12);
        app.mouse_pos = Some((300, 190));
        let drops_before = app.drops.len();
        app.on_inventory_drop_key(true);
        assert_eq!(app.inventory.items[12], (0, 0), "the slot emptied");
        assert_eq!(app.drops.len(), drops_before + 1, "one drop spawned");
        let d = app.drops.last().unwrap();
        assert_eq!(d.item, 63);
        assert_eq!(d.count, 12, "the WHOLE stack");
        assert_eq!(d.pickup_delay, 40);
        assert!(!app.swing.swinging, "no swing");
        // the main row is NOT the hotbar — the HUD row untouched
        assert_eq!(app.hotbar_slots[app.selected_hotbar], (0, 0), "the hotbar untouched");
        // the doClick's button==1 repeat loop the one-shot whole-take
        // answers on plain stacks — safeTake(count, MAX) empties in one
        // call: a second Ctrl+Q on the now-empty slot is silence
        app.on_inventory_drop_key(true);
        assert_eq!(app.drops.len(), drops_before + 1, "still one drop");
    }

    /// THE INVENTORY Q'S OWN GATES (the keyPressed chain + the doClick
    /// THROW arm's own pair): the EMPTY hovered slot silence (the
    /// hasItem() gate), the CARRIED cursor silence (the
    /// getCarried().isEmpty() gate — the held stack the Q never
    /// throws), the hoveredSlot-null silence (the mouse off the slots —
    /// the gate the keyPressed bytecode 39-53 speaks), the world-screen
    /// cross silence (this lane IS the container's own), and the wire
    /// session refusal (the store the server owns).
    #[test]
    fn the_inventory_q_refuses_the_empty_and_the_carried_and_the_wire() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.inventory.items[5] = (62, 7);
        let drops_before = app.drops.len();
        // the hoveredSlot NULL (the cursor between the slots — the
        // mannequin's own region): the keyPressed gate returns false
        app.mouse_pos = Some((332, 157));
        app.on_inventory_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the null hover is silence");
        // the world screen CROSS — this lane the world Q's chain never
        // doubles (the screen gate holds)
        app.screen = ScreenKind::World;
        app.mouse_pos = Some((336, 246));
        app.on_inventory_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the world screen cross is silence");
        app.open_inventory(); // back on the container screen
        // the EMPTY hovered slot (the hasItem() gate — slot 0 the store
        // never carried: origin (240, 239), the cursor inside)
        app.mouse_pos = Some((246, 246));
        app.on_inventory_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the empty hover is silence");
        // the CARRIED cursor (the getCarried().isEmpty() gate — the
        // doClick's own first test; the cursor back over the FULL slot 5
        // so the silence IS the carried gate's own, not the empty slot's)
        app.mouse_pos = Some((336, 246));
        app.inv_carried = (62, 5);
        app.on_inventory_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the carried cursor is silence");
        assert_eq!(app.inventory.items[5], (62, 7), "the store whole");
        assert_eq!(app.inv_carried, (62, 5), "the carry untouched");
        // the Ctrl form keeps every gate
        app.on_inventory_drop_key(true);
        assert_eq!(app.drops.len(), drops_before, "still silence");
        // the WIRE session — the store the server owns
        app.inv_carried = (0, 0);
        app.mouse_pos = Some((336, 246));
        app.world_is_network = true;
        app.on_inventory_drop_key(false);
        assert_eq!(app.drops.len(), drops_before, "the wire refusal holds");
        assert_eq!(app.inventory.items[5], (62, 7), "the wire store whole");
    }

    /// THE RIGHT PRESS'S OWN TABLE (the doClick PICKUP button-1 branch):
    /// the ceiling-half take (5 -> 3 taken, 2 left), the place-one, and
    /// the same-item move-one.
    #[test]
    fn the_right_press_places_one() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.inventory.items[0] = (62, 5);
        // the ceiling-half take
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 0);
        app.on_right_press(ox + 8, oy + 8);
        assert_eq!(app.inventory.items[0], (62, 2), "2 left");
        assert_eq!(app.inv_carried, (62, 3), "3 taken");
        // the place-one into the empty slot 9
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 9);
        app.on_right_press(ox + 8, oy + 8);
        assert_eq!(app.inventory.items[9], (62, 1), "one placed");
        assert_eq!(app.inv_carried, (62, 2), "two ride");
        // the same-item move-one on the next press
        app.on_right_press(ox + 8, oy + 8);
        assert_eq!(app.inventory.items[9], (62, 2), "one more moved");
        assert_eq!(app.inv_carried, (62, 1), "one rides");
    }

    /// THE QUICK-MOVE'S FORWARD SECTIONS (the 26.2 quickMoveStack law —
    /// the inventory menu's own order, the chest's fillFromEnd the other
    /// menus speak): the shift-click moves the whole stack to the OTHER
    /// section, the same-item merges first, the FIRST empty slot takes
    /// the remainder (store 0 forward for the hotbar, store 9 forward
    /// for the main rows).
    #[test]
    fn the_quick_move_walks_the_forward_sections() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        // the main rows: cobblestone x70 at store 9 (30 over the stack
        // ceiling), the hotbar: cobblestone x40 at store 3 (24 room)
        app.inventory.items[9] = (62, 70);
        app.inventory.items[3] = (62, 40);
        // THE SHIFT-CLICK on the main stack: the hotbar's 40 merges to 64
        // first (pass 1), the first EMPTY hotbar slot (store 0) takes the
        // whole 46 remainder (pass 2 — the empty slot takes the stack up
        // to its ceiling, forward)
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 9);
        app.shift_down = true;
        app.on_press(ox + 8, oy + 8);
        app.shift_down = false;
        assert_eq!(app.inventory.items[3], (62, 64), "the merge ceiling");
        assert_eq!(app.inventory.items[0], (62, 46), "the FIRST empty took the rest");
        assert_eq!(app.inventory.items[9], (0, 0), "the source emptied");
        // THE REVERSE: the hotbar stack quick-moves to the main rows —
        // the same-item merge at store 9's neighbors first, the first
        // empty main slot after
        app.inventory.items[0] = (62, 6);
        app.inventory.items[12] = (62, 60);
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 0);
        app.shift_down = true;
        app.on_press(ox + 8, oy + 8);
        app.shift_down = false;
        assert_eq!(app.inventory.items[12], (62, 64), "the main merge ceiling");
        assert_eq!(app.inventory.items[9], (62, 2), "the FIRST main empty (slot 9) took the rest");
        assert_eq!(app.inventory.items[0], (0, 0), "the hotbar source emptied");
    }

    /// THE CLOSE'S ADD-BACK WALK (the vanilla close's own tail): a
    /// carried stack returns to the store (the same-item merges first,
    /// the first empty slot takes the remainder), the full store's
    /// remainder DROPS at the body's feet (the Player.drop law).
    #[test]
    fn the_close_returns_the_carried_to_the_store() {
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        // the carried stack with a same-item home: merges into it
        app.inventory.items[5] = (921, 10); // apple
        app.inv_carried = (921, 7);
        app.close_inventory();
        assert_eq!(app.inventory.items[5], (921, 17), "the merge back");
        assert_eq!(app.inv_carried, (0, 0));
        assert_eq!(app.screen, ScreenKind::World, "the screen back");
        // the carried with NO same-item home: the first empty slot
        app.open_inventory();
        app.inv_carried = (926, 4); // diamond
        app.close_inventory();
        assert_eq!(app.inventory.items[0], (926, 4), "the first empty took it");
        // the FULL store: the remainder drops at the body's feet
        app.open_inventory();
        for it in app.inventory.items.iter_mut() {
            *it = (62, 64);
        }
        app.inv_carried = (62, 9);
        let (bx, by, bz) = {
            let b = app.body.as_ref().unwrap();
            (b.x, b.y, b.z)
        };
        app.close_inventory();
        assert_eq!(app.inv_carried, (0, 0), "the cursor emptied");
        let dropped = app
            .drops
            .iter()
            .find(|d| d.item == 62 && d.count == 9)
            .expect("the remainder dropped");
        assert!((dropped.x - bx).abs() < 1.0 && (dropped.z - bz).abs() < 1.0);
        let _ = by;
    }

    /// THE MANNEQUIN'S OWN LAW (the 26.2 bytecode the round pinned): the
    /// neutral pose when no mouse speaks, the atan turn law on the mouse
    /// (the rect-center delta over 40, atan, *20 — the bodyRot 180 + the
    /// lean), and the VP chain's placement (the feet 28.875*S below the
    /// rect center, the model's center 1.875*S above — the slightly-low
    /// vanilla placement inside the 49x70 rect).
    #[test]
    fn the_mannequin_law_pins_the_vanilla_chain() {
        // THE TURN LAW: the neutral pose (the headless stand-in)
        assert_eq!(mannequin_turn(None, 232, 97), (180.0, 0.0));
        // the mouse 40 px left of the rect center (the i32 mouse the
        // real input speaks — the expected folds the ACTUAL 40.5 delta
        // the center's half-pixel keeps): atan(d/40)*20 = the lean the
        // vanilla radians-as-degrees soup speaks
        let (x1, y1, x2, y2) = MANNEQUIN_RECT;
        let cx = (232 + x1 + 232 + x2) as f32 / 2.0;
        let cy = (97 + y1 + 97 + y2) as f32 / 2.0;
        let mx = cx as i32 - 40;
        let d = (cx - mx as f32) / 40.0;
        let (yaw, pitch) = mannequin_turn(Some((mx, cy as i32)), 232, 97);
        assert!((yaw - (180.0 + 20.0 * d.atan())).abs() < 1e-4);
        assert!(pitch.abs() < 1e-4, "the vertical delta zero");
        // THE VP: the feet and the model's center project through the
        // chain the raster's own NDC mapping consumes
        let vp = mannequin_vp(232, 97, 1.0, 640.0, 360.0, 0.0);
        let project = |p: [f32; 3]| -> (f32, f32) {
            let c = vp.transform_point(crate::math::Vec3::new(p[0], p[1], p[2]));
            let ndc_x = c[0] / c[3];
            let ndc_y = c[1] / c[3];
            (
                (ndc_x * 0.5 + 0.5) * 640.0,
                (1.0 - (ndc_y * 0.5 + 0.5)) * 360.0,
            )
        };
        let (fx, fy) = project([0.0, 0.0, 0.0]);
        let (mx, my) = project([0.0, 0.9, 0.0]);
        assert!((fx - cx).abs() < 0.01, "the feet centered: {fx} vs {cx}");
        assert!(
            (fy - (cy + 28.875)).abs() < 0.01,
            "the feet 28.875 below: {fy}"
        );
        assert!(
            (my - (cy + 1.875)).abs() < 0.01,
            "the center 1.875 below (the 0.0625 lift's own quirk): {my}"
        );
        // both inside the mannequin rect (the 49x70 window the PiP owns)
        let (rx0, ry0, rx1, ry1) = (232 + x1, 97 + y1, 232 + x2, 97 + y2);
        assert!(fx >= rx0 as f32 && fx < rx1 as f32);
        assert!(fy >= ry0 as f32 && fy < ry1 as f32);
        assert!(mx >= rx0 as f32 && mx < rx1 as f32);
        assert!(my >= ry0 as f32 && my < ry1 as f32);
    }

    /// THE SCREEN'S OWN PIXELS: the background texture blits (the panel
    /// face the bevel's own gray speaks), the store's icons and counts
    /// land in the slots (the pair against the empty store differs), and
    /// the mannequin's body pixels fill the hole (the model-loaded gate
    /// the sha1 walk keeps — the no-cache boot skips the pass honestly).
    #[test]
    fn the_inventory_screen_renders_the_store() {
        // the test's own pixel reader (the fb's public color vec)
        fn px(fb: &crate::raster::Framebuf, x: usize, y: usize) -> [u8; 3] {
            let o = (y * fb.w + x) * 3;
            [fb.color[o], fb.color[o + 1], fb.color[o + 2]]
        }
        // the cache root the loaders' prefix walk keeps (the CWD the
        // cargo test process speaks varies — the absent cache the
        // honest skip answers, the font tests' real() gate the shape)
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        // the EMPTY store first (the baseline the pair speaks against)
        let mut fb = crate::raster::Framebuf::new(640, 360);
        let mut assets = GuiAssets::open(&root);
        app.render(&mut fb, &mut assets);
        let empty = fb.color.clone();
        // THE STAGED STORE: the same loadout the headless staging speaks
        app.inventory.items[0] = (62, 27);
        app.inventory.items[1] = (63, 16);
        app.hotbar_slots = app.inventory.hotbar();
        let mut fb = crate::raster::Framebuf::new(640, 360);
        app.render(&mut fb, &mut assets);
        // the panel face pixel (the texture's own 198 gray at panel
        // (50, 81) — between the hole and the rows, no chrome)
        let face = px(&fb, 232 + 50, 97 + 81);
        assert_eq!(face, [198, 198, 198], "the background blit speaks");
        // the slot pair differs (the icons painted over the chrome)
        let (sx, sy) = inventory_slot_origin((232, 97), 0);
        let mut diff = 0usize;
        for dy in 0..16 {
            for dx in 0..16 {
                if px(&fb, sx as usize + 1 + dx, sy as usize + 1 + dy)
                    != [
                        empty[((sy as usize + 1 + dy) * fb.w + sx as usize + 1 + dx) * 3],
                        empty[((sy as usize + 1 + dy) * fb.w + sx as usize + 1 + dx) * 3 + 1],
                        empty[((sy as usize + 1 + dy) * fb.w + sx as usize + 1 + dx) * 3 + 2],
                    ]
                {
                    diff += 1;
                }
            }
        }
        assert!(diff > 40, "the icon painted: {diff} pixels differ");
        // the mannequin's body pixels inside the hole (the model gate —
        // the same root the loader walks)
        if crate::avatar::AvatarModel::load(&root).is_some() {
            let mut diff = 0usize;
            for y in 110..165 {
                for x in 262..303 {
                    if px(&fb, x, y) != [0, 0, 0] {
                        diff += 1;
                    }
                }
            }
            assert!(diff > 200, "the mannequin painted: {diff} pixels");
        }
    }

    /// THE MANNEQUIN'S ARMOR (the HumanoidArmorLayer walk the store's
    /// own rows keep): the EMPTY store renders pixel-identical twice
    /// (the no-armor path adds ZERO quads — the golden law's own gate),
    /// the iron kit paints the head/chest/legs (the equipment textures
    /// the sha1 table verified), the elytra renders NOTHING (the
    /// wings-layer asset the humanoid slots never texture), and the
    /// leather chestplate rides its dyeable composite (the overlay
    /// over the tinted base the client info JSON speaks).
    #[test]
    fn the_mannequin_wears_the_store_armor() {
        // the runtime root the loaders' prefix walk keeps (the absent
        // cache the honest skip answers — the mannequin tests' own law)
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let Some(_) = crate::avatar::AvatarModel::load(&root) else {
            return; // the skin asset gate — the armor rides the same honesty
        };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        let mut assets = GuiAssets::open(&root);
        let bare = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let bare_twice = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color
        };
        assert_eq!(bare, bare_twice, "the empty-armor path adds zero quads");
        let px = |color: &[u8], x: usize, y: usize| -> [u8; 3] {
            let o = (y * 640 + x) * 3;
            [color[o], color[o + 1], color[o + 2]]
        };
        // the mannequin's own window (the hole the PiP owns — the armor
        // slots' icons never overlap it)
        let diff_in_window = |a: &[u8], b: &[u8]| -> usize {
            let mut diff = 0usize;
            for y in 110..165 {
                for x in 262..303 {
                    if px(a, x, y) != px(b, x, y) {
                        diff += 1;
                    }
                }
            }
            diff
        };
        // THE IRON KIT (the SLOT_IDS order: HEAD, CHEST, LEGS, FEET)
        let id = |name: &str| mc_registry::item_id_by_name(name).expect("the registry speaks");
        app.inventory.armor = [
            (id("iron_helmet"), 1),
            (id("iron_chestplate"), 1),
            (id("iron_leggings"), 1),
            (id("iron_boots"), 1),
        ];
        let iron = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let iron_diff = diff_in_window(&bare, &iron);
        assert!(iron_diff > 120, "the iron kit painted: {iron_diff} pixels");
        // each body region the kit covers changed (the helmet's crown
        // band, the chestplate's torso band, the legs' own band)
        let band_diff = |a: &[u8], b: &[u8], y0: usize, y1: usize| -> usize {
            let mut diff = 0usize;
            for y in y0..y1 {
                for x in 262..303 {
                    if px(a, x, y) != px(b, x, y) {
                        diff += 1;
                    }
                }
            }
            diff
        };
        assert!(band_diff(&bare, &iron, 108, 122) > 5, "the helmet painted");
        assert!(band_diff(&bare, &iron, 126, 146) > 5, "the chestplate painted");
        assert!(band_diff(&bare, &iron, 148, 165) > 5, "the legs painted");
        // the cache holds the TWO layer entries the iron kit names (the
        // humanoid dir the head/chest/feet share, the leggings dir the
        // legs' own layer rides) — both sha1-verified loads
        use mc_registry::generated::equipment;
        assert_eq!(app.armor_textures.len(), 2);
        assert!(matches!(
            app.armor_textures.get(&format!("{}/iron", equipment::HUMANOID_DIR)),
            Some(Some(_))
        ));
        assert!(matches!(
            app.armor_textures.get(&format!("{}/iron", equipment::LEGGINGS_DIR)),
            Some(Some(_))
        ));
        // THE ELYTRA'S HONEST MISS: the CHEST slot's piece the
        // equipment asset never names (the wings layer the humanoid
        // slots never texture) renders nothing — the mannequin back to
        // the bare skin (the shouldRender gate's empty-asset verdict;
        // the piece itself rides an item icon — the flat slot path)
        app.inventory.armor = [(0, 0), (id("elytra"), 1), (0, 0), (0, 0)];
        let elytra = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let elytra_diff = diff_in_window(&bare, &elytra);
        assert_eq!(elytra_diff, 0, "the elytra rides no humanoid layer");
        // THE LEATHER COMPOSITE: the dyeable pair loads (the base + the
        // untinted overlay), the chest band paints the tinted brown
        app.inventory.armor = [(0, 0), (id("leather_chestplate"), 1), (0, 0), (0, 0)];
        let leather = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        assert!(matches!(
            app.armor_textures.get(&format!("{}/leather", equipment::HUMANOID_DIR)),
            Some(Some(_))
        ));
        assert!(matches!(
            app.armor_textures
                .get(&format!("{}/leather_overlay", equipment::HUMANOID_DIR)),
            Some(Some(_))
        ));
        let mut leather_diff = 0usize;
        for y in 120..155 {
            for x in 262..303 {
                if px(&bare, x, y) != px(&leather, x, y) {
                    leather_diff += 1;
                }
            }
        }
        assert!(leather_diff > 60, "the leather chest painted: {leather_diff}");
    }

    /// THE MANNEQUIN'S HEAD-BLOCK (the CustomHeadLayer item branch the
    /// carved pumpkin rides — the head stack the armor walk refuses
    /// still paints the mannequin): the pumpkin's block pixels cover
    /// the head (the bare-skin diff speaks), the equipment loads stay
    /// EMPTY (the asset fold's own verdict — the head-block lane is no
    /// armor lane), and the skull family the `wornHeadType` branch
    /// keeps renders NOTHING (the special-models' follow-up — the
    /// honest silence the elytra's own miss speaks).
    #[test]
    fn the_mannequin_wears_the_carved_pumpkin() {
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let Some(_) = crate::avatar::AvatarModel::load(&root) else {
            return; // the skin asset gate — the head-block rides the same honesty
        };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        let mut assets = GuiAssets::open(&root);
        let bare = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let px = |color: &[u8], x: usize, y: usize| -> [u8; 3] {
            let o = (y * 640 + x) * 3;
            [color[o], color[o + 1], color[o + 2]]
        };
        let diff_in_window = |a: &[u8], b: &[u8]| -> usize {
            let mut diff = 0usize;
            for y in 96..168 {
                for x in 262..303 {
                    if px(a, x, y) != px(b, x, y) {
                        diff += 1;
                    }
                }
            }
            diff
        };
        // THE PUMPKIN PAINTS (the 0.625 block over the head — bigger
        // than the helmet the armor lane paints, the overhang ABOVE the
        // crown the 2.0635 top speaks)
        let id = |name: &str| mc_registry::item_id_by_name(name).expect("the registry speaks");
        app.inventory.armor = [(id("carved_pumpkin"), 1), (0, 0), (0, 0), (0, 0)];
        let pumpkin = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let pumpkin_diff = diff_in_window(&bare, &pumpkin);
        // 98 at the raw-order fix (v0.3.245): the CORRECT paint stays
        // inside the head block (the carved face replaces the skin's
        // own, the dark carved texels matching the bare render's dark
        // hair/eyes where they overlap) — the old bowtie garble scored
        // higher only because its sheared survivor spilled over the
        // gui background. The regression floor: no paint scores ~0.
        assert!(pumpkin_diff > 60, "the pumpkin painted: {pumpkin_diff}");
        // the equipment loads stay EMPTY (the asset fold refuses the
        // pumpkin — the head-block lane speaks no armor texture)
        assert!(app.armor_textures.is_empty());
    }

    /// THE MANNEQUIN'S WORN SKULL (the CustomHeadLayer wornHeadType
    /// branch the skeleton skull rides — the model straight through the
    /// head's own chain, the 1.1875 scale the submitSkull walk keeps):
    /// the skull paints the mannequin (the entity diffuse the skin's
    /// own law shades it), the equipment loads stay EMPTY (the asset
    /// fold refuses the whole family), and the piglin's ears + the
    /// dragon's jaw ride their part-tree poses (the quad counts the
    /// dump speaks).
    #[test]
    fn the_mannequin_wears_the_skeleton_skull() {
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let Some(_) = crate::avatar::AvatarModel::load(&root) else { return };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        let mut assets = GuiAssets::open(&root);
        let bare = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let id = |name: &str| mc_registry::item_id_by_name(name).expect("the registry speaks");
        app.inventory.armor = [(id("skeleton_skull"), 1), (0, 0), (0, 0), (0, 0)];
        let skull = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let px = |color: &[u8], x: usize, y: usize| -> [u8; 3] {
            let o = (y * 640 + x) * 3;
            [color[o], color[o + 1], color[o + 2]]
        };
        let mut skull_diff = 0usize;
        for y in 96..168 {
            for x in 262..303 {
                if px(&bare, x, y) != px(&skull, x, y) {
                    skull_diff += 1;
                }
            }
        }
        assert!(skull_diff > 40, "the worn skull painted: {skull_diff}");
        // the asset fold's own verdict — the family speaks no armor texture
        assert!(app.armor_textures.is_empty());
    }

    #[test]
    fn the_skull_icon_bakes_in_its_slot() {
        // THE /16 LAW (the vanilla Cube constructor's own division):
        // the dump-backed special polygons bake in block units — the
        // skeleton skull's icon paints INSIDE the head slot's 16x16
        // (the former raw-texel bake spread a ~180px smear across the
        // screen — the regressions this test buries)
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let Some(_) = crate::avatar::AvatarModel::load(&root) else { return };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        let mut assets = GuiAssets::open(&root);
        let bare = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let id = mc_registry::item_id_by_name("skeleton_skull").expect("the registry speaks");
        app.inventory.armor = [(id, 1), (0, 0), (0, 0), (0, 0)];
        let skull = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let px = |c: &[u8], x: usize, y: usize| -> [u8; 3] {
            let o = (y * 640 + x) * 3;
            [c[o], c[o + 1], c[o + 2]]
        };
        // the head slot's own region (panel 232,97 + (8,8), the +1 inset
        // the icon draw keeps — a 2px margin around the 16x16), PLUS the
        // mannequin's own window (the worn skull the wornHeadType lane
        // paints — the diff law's second home)
        let in_slot = |x: usize, y: usize| x >= 239 && x < 258 && y >= 104 && y < 123;
        let in_window = |x: usize, y: usize| x >= 262 && x < 303 && y >= 96 && y < 168;
        let mut slot_px = 0usize;
        let mut strays = Vec::new();
        for y in 0..360 {
            for x in 0..640 {
                if px(&bare, x, y) != px(&skull, x, y) {
                    if in_slot(x, y) {
                        slot_px += 1;
                    } else if !in_window(x, y) {
                        if strays.len() < 8 {
                            strays.push((x, y));
                        }
                    }
                }
            }
        }
        assert!(slot_px > 100, "the skull icon painted the slot: {slot_px}");
        assert!(strays.is_empty(), "the icon stayed in its slot: {strays:?}");
    }

    /// THE MANNEQUIN'S HELD ITEM (the ItemInHandLayer
    /// submitArmWithItem walk the selected hotbar stack keeps — the
    /// main hand the extraction fills): the selected slot's stone
    /// paints the mannequin's hand (the bare-skin diff speaks), the
    /// empty store renders pixel-identical twice (the no-item path
    /// adds ZERO quads — the golden law's own gate), a DIFFERENT
    /// selected slot keeps the mannequin bare (the selection the main
    /// hand follows), and the equipment loads stay EMPTY (the held
    /// lane is no armor lane).
    #[test]
    fn the_mannequin_holds_the_selected_stack() {
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let Some(_) = crate::avatar::AvatarModel::load(&root) else { return };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        let mut assets = GuiAssets::open(&root);
        let bare = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let bare_twice = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color
        };
        assert_eq!(bare, bare_twice, "the empty-hand path adds zero quads");
        let px = |c: &[u8], x: usize, y: usize| -> [u8; 3] {
            let o = (y * 640 + x) * 3;
            [c[o], c[o + 1], c[o + 2]]
        };
        // the mannequin's own neighborhood (the window the PiP owns +
        // the held item's spill past its chrome — the hand's own
        // reach), the pair the held lane's paint speaks through
        let diff_in_window = |a: &[u8], b: &[u8]| -> usize {
            let mut diff = 0usize;
            for y in 96..168 {
                for x in 250..320 {
                    if px(a, x, y) != px(b, x, y) {
                        diff += 1;
                    }
                }
            }
            diff
        };
        // THE SELECTED STACK (the stone in the main hand — slot 0 the
        // default selected speaks)
        let id = mc_registry::item_id_by_name("stone").expect("the registry speaks");
        app.inventory.items[app.selected_hotbar] = (id, 27);
        let held = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let held_diff = diff_in_window(&bare, &held);
        assert!(held_diff > 20, "the held stone painted: {held_diff} pixels");
        // no strays outside the mannequin's neighborhood (the slot
        // icon the slot pass paints rides its own region — the slot 0
        // icon the store's own draw keeps; the rest is the held lane's)
        let (sx, sy) = inventory_slot_origin((232, 97), 0);
        let mut strays = Vec::new();
        for y in 0..360 {
            for x in 0..640 {
                if px(&bare, x, y) != px(&held, x, y) {
                    let in_window = x >= 250 && x < 320 && y >= 96 && y < 168;
                    let in_slot0 = x >= sx as usize && x < sx as usize + 18
                        && y >= sy as usize && y < sy as usize + 18;
                    if !in_window && !in_slot0 {
                        if strays.len() < 8 {
                            strays.push((x, y));
                        }
                    }
                }
            }
        }
        assert!(strays.is_empty(), "the paint stayed home: {strays:?}");
        // the equipment loads stay EMPTY (the held lane is no armor lane)
        assert!(app.armor_textures.is_empty(), "no armor loads");
        // A DIFFERENT SELECTION (slot 3 empty): the main hand's stack
        // the selection names — the mannequin back to bare
        app.selected_hotbar = 3;
        let other = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        assert_eq!(
            diff_in_window(&bare, &other),
            0,
            "the empty selected slot keeps the hand bare"
        );
        // THE SELECTED SLOT'S OWN STACK (the sword at slot 3 — the
        // selection moves the item's paint)
        let sword = mc_registry::item_id_by_name("iron_sword").expect("the registry speaks");
        app.inventory.items[app.selected_hotbar] = (sword, 1);
        let swd = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let swd_diff = diff_in_window(&bare, &swd);
        assert!(swd_diff > 5, "the held sword painted: {swd_diff} pixels");
    }

    /// THE OFFHAND'S OWN LANE (ItemInHandLayer.submit's SECOND
    /// submitArmWithItem — the leftHandItemState/Stack pair the
    /// extraction fills, the mannequin's OFFHAND slot 45 the store
    /// keeps): the offhand stack paints the mannequin's LEFT side the
    /// leftArm chain rides, the empty offhand adds zero quads, the
    /// paint stays home (the mannequin's window + the offhand slot's
    /// own icon the slot pass draws), the equipment loads stay empty.
    #[test]
    fn the_mannequin_holds_the_offhand_stack() {
        let root = ["assets-cache/jar", "../assets-cache/jar", "../../assets-cache/jar"]
            .iter()
            .map(std::path::Path::new)
            .find(|p| p.join("gui/container/inventory.png").exists());
        let Some(root) = root else { return };
        let Some(_) = crate::avatar::AvatarModel::load(&root) else { return };
        let mut app = App::new(3);
        app.enter_world();
        app.spawn_offline_body();
        app.open_inventory();
        let mut assets = GuiAssets::open(&root);
        let bare = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let bare_twice = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color
        };
        assert_eq!(bare, bare_twice, "the empty-offhand path adds zero quads");
        let px = |c: &[u8], x: usize, y: usize| -> [u8; 3] {
            let o = (y * 640 + x) * 3;
            [c[o], c[o + 1], c[o + 2]]
        };
        let diff_in_window = |a: &[u8], b: &[u8]| -> usize {
            let mut diff = 0usize;
            for y in 96..168 {
                for x in 250..320 {
                    if px(a, x, y) != px(b, x, y) {
                        diff += 1;
                    }
                }
            }
            diff
        };
        // THE OFFHAND STACK (the stone rides slot 45 — the main hand
        // stays empty so the paint is the offhand lane's alone)
        let id = mc_registry::item_id_by_name("stone").expect("the registry speaks");
        app.inventory.offhand[0] = (id, 5);
        let off = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        let off_diff = diff_in_window(&bare, &off);
        assert!(off_diff > 20, "the offhand stone painted: {off_diff} pixels");
        // no strays outside the mannequin's neighborhood (the offhand
        // slot's own icon the slot pass paints rides its region — the
        // rest is the offhand lane's)
        let (ox, oy) = offhand_slot_origin((232, 97));
        let mut strays = Vec::new();
        for y in 0..360 {
            for x in 0..640 {
                if px(&bare, x, y) != px(&off, x, y) {
                    let in_window = x >= 250 && x < 320 && y >= 96 && y < 168;
                    let in_slot = x >= ox as usize && x < ox as usize + 18
                        && y >= oy as usize && y < oy as usize + 18;
                    if !in_window && !in_slot {
                        if strays.len() < 8 {
                            strays.push((x, y));
                        }
                    }
                }
            }
        }
        assert!(strays.is_empty(), "the paint stayed home: {strays:?}");
        // the equipment loads stay EMPTY (the offhand lane is no armor
        // lane — the main hand's own verdict this lane shares)
        assert!(app.armor_textures.is_empty(), "no armor loads");
        // THE CLEARED OFFHAND (slot 45 back to empty): the mannequin
        // back to bare — the lane's gate the count's zero keeps
        app.inventory.offhand[0] = (0, 0);
        let cleared = {
            let mut fb = crate::raster::Framebuf::new(640, 360);
            app.render(&mut fb, &mut assets);
            fb.color.clone()
        };
        assert_eq!(
            diff_in_window(&bare, &cleared),
            0,
            "the empty offhand keeps the hand bare"
        );
    }

    /// THE WINDOW-0 WIRE PICKUP (the vanilla AbstractContainerScreen's
    /// own mouseClicked over the player's OWN menu — the containerId 0
    /// the InventoryMenu's ctor pins): the left press on a main-grid
    /// cell the live store's belief feeds — the whole stack rides the
    /// cursor, the changed slot + the post-click cursor the packet
    /// speaks, the revision the feed's own state_id rides — and the
    /// OFFLINE store the wire world never touches (the two lanes
    /// never mix).
    #[test]
    fn the_wire_inventory_click_speaks_the_window0_pickup() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let dirt = mc_registry::item_id_by_name("dirt").unwrap();
        // the window-0 sync: the main grid's cell (store 12 = the
        // menu's own slot id 12 — the store >= 9 the identity keeps)
        // carries 32 dirt, the revision 7 the packets spoke last
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[12] = (dirt, 32);
        app.live_inventory_updated(slots, Vec::new(), 7, (0, 0));
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 12);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(
            app.live_inv_slots[12],
            (0, 0),
            "the believed slot the pickup emptied"
        );
        assert_eq!(app.live_inv_carried, (dirt, 32), "the cursor's own take");
        assert_eq!(
            app.inventory.items[12], (0, 0),
            "the offline store the wire world never touches"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.window_id, 0, "the player's OWN menu the ctor pins");
                assert_eq!(c.state_id, 7, "the revision the feed spoke");
                assert_eq!(c.slot, 12, "the menu's own slot id the store keeps");
                assert_eq!(c.button, 0);
                assert_eq!(c.input, crate::world_view::ContainerInput::Pickup);
                assert_eq!(c.changed, vec![(12, (0, 0))]);
                assert_eq!(c.carried, (dirt, 32));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE HOTBAR CELL'S OWN USE_ROW ID (the store index's menu law —
    /// the hotbar row the menu ids 36..44 the USE_ROW constants keep,
    /// NOT the store's own 0..8): the right press places ONE from the
    /// carried stack (the split-table's own law), the HUD row's
    /// belief follows the menu ids the sync replaces wholesale.
    #[test]
    fn the_wire_inventory_hotbar_click_follows_the_use_row_ids() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let dirt = mc_registry::item_id_by_name("dirt").unwrap();
        // the hotbar cell store 3 = the menu's own slot id 39 (the
        // 36 + store the USE_ROW law keys), the cursor carries 10
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[39] = (0, 0);
        app.live_inventory_updated(slots, Vec::new(), 9, (dirt, 10));
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 3);
        app.on_right_press(ox + 8, oy + 8);
        assert_eq!(
            app.live_inv_slots[39],
            (dirt, 1),
            "the ONE item the right press placed"
        );
        assert_eq!(app.live_inv_carried, (dirt, 9), "the cursor's own split");
        assert_eq!(
            app.hotbar_slots[3],
            (dirt, 1),
            "the HUD row's belief the menu id keys"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, 39, "the USE_ROW's own menu id");
                assert_eq!(c.button, 1);
                assert_eq!(c.input, crate::world_view::ContainerInput::Pickup);
                assert_eq!(c.changed, vec![(39, (dirt, 1))]);
                assert_eq!(c.carried, (dirt, 9));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE QUICK-MOVE'S MENU NUMBERING (the shift-click the
    /// quickMoveStack walk speaks): the main grid's source rides the
    /// HOTBAR's merge order (the store 0..8 the hotbar stores), the
    /// changed indices map BACK to the menu ids (the store 4 -> 40,
    /// the store 0 -> 36 — the USE_ROW law the pickup test keeps),
    /// the HUD row the belief's own law follows, the armor column
    /// untouched.
    #[test]
    fn the_wire_inventory_quick_move_rides_the_menu_numbering() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.on_shift_down(true);
        let dirt = mc_registry::item_id_by_name("dirt").unwrap();
        // the main grid's source (store 14 = menu 14) carries 60, the
        // hotbar cells the merge order walks: store 4 (menu 40) holds
        // 10 (room 54), store 0 (menu 36) the first empty — the walk
        // feeds 64 + 6, the source empties
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[14] = (dirt, 60);
        slots[40] = (dirt, 10);
        app.live_inventory_updated(slots, Vec::new(), 3, (0, 0));
        let (ox, oy) = inventory_slot_origin(app.inv_panel, 14);
        app.on_press(ox + 8, oy + 8);
        assert_eq!(app.live_inv_slots[14], (0, 0), "the source's own empty");
        assert_eq!(app.live_inv_slots[40], (dirt, 64), "the merge's own cap");
        assert_eq!(app.live_inv_slots[36], (dirt, 6), "the remainder's own slot");
        assert_eq!(app.hotbar_slots[4], (dirt, 64), "the HUD belief rides");
        assert_eq!(app.hotbar_slots[0], (dirt, 6));
        assert!(
            app.live_inv_slots[5..9].iter().all(|&s| s == (0, 0)),
            "the armor column the walk never touched"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.window_id, 0);
                assert_eq!(c.slot, 14);
                assert_eq!(
                    c.input,
                    crate::world_view::ContainerInput::QuickMove,
                    "the shift the hasShiftDown query speaks"
                );
                assert_eq!(
                    c.changed,
                    vec![(14, (0, 0)), (40, (dirt, 64)), (36, (dirt, 6))],
                    "the menu-keyed deltas the walk mapped"
                );
                assert_eq!(c.carried, (0, 0), "the quick-move the cursor never rides");
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        app.on_shift_down(false);
    }

    /// THE ARMOR COLUMN'S OWN LANES (the piece slot's click the
    /// menu ids 5..8 key): the shift-click moves the piece to the
    /// store rows (`predict_quick_move_to_store` — the store 9 the
    /// forward range's first empty), the plain press picks the piece
    /// up (the empty cursor's whole take the pickup table speaks).
    #[test]
    fn the_wire_inventory_armor_lanes_speak_their_menu_ids() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let chest = mc_registry::item_id_by_name("iron_chestplate").unwrap();
        // THE SHIFT LANE: the chestplate at the armor slot menu 6
        // (k=1) moves to the store's first row (store 9 = menu 9)
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[6] = (chest, 1);
        app.live_inventory_updated(slots, Vec::new(), 4, (0, 0));
        app.on_shift_down(true);
        let (ax, ay) = armor_slot_origin(app.inv_panel, 1);
        app.on_press(ax + 8, ay + 8);
        assert_eq!(app.live_inv_slots[6], (0, 0), "the piece's own move");
        assert_eq!(app.live_inv_slots[9], (chest, 1), "the store's own take");
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, 6, "the armor's own menu id");
                assert_eq!(c.input, crate::world_view::ContainerInput::QuickMove);
                assert_eq!(c.changed, vec![(9, (chest, 1))]);
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // THE PLAIN PICKUP: the fresh piece rides again (the sync's
        // own word), the empty cursor takes it whole
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[6] = (chest, 1);
        app.live_inventory_updated(slots, Vec::new(), 5, (0, 0));
        app.on_shift_down(false);
        app.on_press(ax + 8, ay + 8);
        assert_eq!(app.live_inv_slots[6], (0, 0));
        assert_eq!(app.live_inv_carried, (chest, 1), "the piece the cursor holds");
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, 6);
                assert_eq!(c.input, crate::world_view::ContainerInput::Pickup);
                assert_eq!(c.changed, vec![(6, (0, 0))]);
                assert_eq!(c.carried, (chest, 1));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE THROW LANE (the outside press the doClick THROW arm
    /// speaks — the slot -999 the wire's own sentinel): the LEFT
    /// press drops the whole carried stack, the RIGHT splits one, the
    /// drop entity the SERVER spawns (the wire's own Add Entity lane
    /// — the offline stand-in's local spawn never rides), the EMPTY
    /// cursor's press stays silent (the THROW arm's own isEmpty
    /// guard).
    #[test]
    fn the_wire_inventory_throw_outside_speaks_the_999_lane() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let dirt = mc_registry::item_id_by_name("dirt").unwrap();
        // the LEFT press outside the panel: the whole stack rides
        let slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        app.live_inventory_updated(slots, Vec::new(), 11, (dirt, 5));
        app.on_press(app.inv_panel.0 - 12, app.inv_panel.1 + 90);
        assert_eq!(app.live_inv_carried, (0, 0), "the whole stack's own drop");
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, -999, "the THROW's own sentinel");
                assert_eq!(c.input, crate::world_view::ContainerInput::Throw);
                assert_eq!(c.changed, Vec::new(), "no slot the throw touched");
                assert_eq!(c.carried, (0, 0));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // THE RIGHT press: the ONE item the split speaks
        let slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        app.live_inventory_updated(slots, Vec::new(), 12, (dirt, 5));
        app.on_right_press(app.inv_panel.0 - 12, app.inv_panel.1 + 90);
        assert_eq!(app.live_inv_carried, (dirt, 4), "the one the split kept");
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, -999);
                assert_eq!(c.button, 1);
                assert_eq!(c.carried, (dirt, 4));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // THE EMPTY CURSOR: the press stays silent (no packet)
        let slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        app.live_inventory_updated(slots, Vec::new(), 13, (0, 0));
        app.on_press(app.inv_panel.0 - 12, app.inv_panel.1 + 90);
        assert!(
            click_rx.try_recv().is_err(),
            "the empty cursor the THROW arm's guard keeps silent"
        );
    }

    /// THE RESULT SLOT'S OWN TAKE (the window-0 wire lane's onTake —
    /// the plain press the result rides): the LEFT press the WHOLE
    /// result takes (the cursor (planks, 4) holds), the believed cell
    /// the onTake's per-cell removeItem empties, the recompute's own
    /// EMPTY verdict the result keeps; the RIGHT press the
    /// half-rounded-up arm speaks; the changed slots the walk's
    /// actual mutations name (the cell then the verdict, the order
    /// the onTake walk keeps).
    #[test]
    fn the_wire_inventory_result_take_speaks_the_on_take_consume() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        // the recipe the belief speaks: one log in the cell menu 1,
        // the result (planks, 4) the server's sync spoke
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[1] = (log, 1);
        slots[0] = (planks, 4);
        app.live_inventory_updated(slots, Vec::new(), 7, (0, 0));
        let (rx, ry) = craft_slot_origin(app.inv_panel, 4);
        // THE LEFT PRESS: the whole result rides the cursor, the
        // onTake the cell consumes, the recompute's EMPTY verdict lands
        app.on_press(rx + 8, ry + 8);
        assert_eq!(
            app.live_inv_carried, (planks, 4),
            "the whole result the cursor takes"
        );
        assert_eq!(app.live_inv_slots[1], (0, 0), "the cell the onTake consumed");
        assert_eq!(
            app.live_inv_slots[0], (0, 0),
            "the recompute's own EMPTY verdict"
        );
        assert_eq!(
            app.inventory.items[12], (0, 0),
            "the offline store the wire world never touches"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.window_id, 0, "the player's OWN menu the ctor pins");
                assert_eq!(c.state_id, 7, "the revision the feed spoke");
                assert_eq!(c.slot, 0, "the result slot's own menu id");
                assert_eq!(c.button, 0);
                assert_eq!(c.input, crate::world_view::ContainerInput::Pickup);
                assert_eq!(
                    c.changed,
                    vec![(1, (0, 0)), (0, (0, 0))],
                    "the onTake's own deltas — the cell then the verdict"
                );
                assert_eq!(c.carried, (planks, 4));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // THE RIGHT PRESS: the half-rounded-up arm the secondary speaks
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[1] = (log, 1);
        slots[0] = (planks, 4);
        app.live_inventory_updated(slots, Vec::new(), 8, (0, 0));
        app.on_right_press(rx + 8, ry + 8);
        assert_eq!(
            app.live_inv_carried, (planks, 2),
            "the half-rounded-up the result count speaks"
        );
        assert_eq!(app.live_inv_slots[1], (0, 0));
        assert_eq!(app.live_inv_slots[0], (0, 0));
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.button, 1);
                assert_eq!(c.changed, vec![(1, (0, 0)), (0, (0, 0))]);
                assert_eq!(c.carried, (planks, 2));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE MERGE ARM'S OWN WALK (the carried-same-item take — the
    /// carried's own space caps the take, the grow the consumer
    /// keeps): the onTake's cell decrement the belief rides, the
    /// recipe's REPEAT the recompute speaks (the re-spoken verdict
    /// the diff law never names — the changed vec the cell alone
    /// carries), the FULL carried the space-0 refusal keeps (no
    /// mutation, the packet rides with the empty changed).
    #[test]
    fn the_wire_inventory_result_merge_rides_the_space_cap() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        // the cursor holds 2 planks, the cell 3 logs, the result 4
        // planks — the space 62 caps the take at the result's own 4
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[1] = (log, 3);
        slots[0] = (planks, 4);
        app.live_inventory_updated(slots, Vec::new(), 9, (planks, 2));
        let (rx, ry) = craft_slot_origin(app.inv_panel, 4);
        app.on_press(rx + 8, ry + 8);
        assert_eq!(
            app.live_inv_carried, (planks, 6),
            "the merge the carried's own space keeps"
        );
        assert_eq!(
            app.live_inv_slots[1], (log, 2),
            "the one log the onTake consumed"
        );
        assert_eq!(
            app.live_inv_slots[0], (planks, 4),
            "the recipe's REPEAT the recompute re-spoke"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, 0);
                assert_eq!(c.input, crate::world_view::ContainerInput::Pickup);
                assert_eq!(
                    c.changed,
                    vec![(1, (log, 2))],
                    "the re-spoken verdict the diff law never names"
                );
                assert_eq!(c.carried, (planks, 6));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // THE FULL CARRIED: the space 0 refuses — the belief stays,
        // the packet rides with the empty changed (the walk's own law)
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[1] = (log, 3);
        slots[0] = (planks, 4);
        app.live_inventory_updated(slots, Vec::new(), 10, (planks, 64));
        app.on_press(rx + 8, ry + 8);
        assert_eq!(
            app.live_inv_carried, (planks, 64),
            "the full carried the space-0 refusal keeps"
        );
        assert_eq!(app.live_inv_slots[1], (log, 3), "the cell untouched");
        assert_eq!(app.live_inv_slots[0], (planks, 4), "the result untouched");
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.changed, Vec::new(), "no slot the refusal touched");
                assert_eq!(c.carried, (planks, 64));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE CELL PLACE'S OWN PREVIEW + THE MAYPLACE REFUSALS (the
    /// result slot's own mayPlace-false law): the carried log the
    /// cell place rides (the uniform pickup table), the mutation's
    /// slotsChanged ask the recipe verdict answers INSTANTLY (the
    /// (planks, 4) preview the client computes — the changed vec the
    /// cell then the verdict names); the empty result the carried
    /// stack never takes (the place arm's refusal), the different
    /// carried the non-empty result never swaps (the
    /// isSameItemSameComponents silence) — both refusals the belief
    /// untouched keeps, the packets the walk's law still sends.
    #[test]
    fn the_wire_inventory_cell_place_previews_and_the_result_refuses() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        let dirt = mc_registry::item_id_by_name("dirt").unwrap();
        // (a) THE PLACE + THE PREVIEW: the carried 5 logs the cell
        // menu 1 takes, the recompute the (planks, 4) verdict speaks
        app.live_inventory_updated(
            [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS],
            Vec::new(),
            11,
            (log, 5),
        );
        let (cx, cy) = craft_slot_origin(app.inv_panel, 0);
        app.on_press(cx + 8, cy + 8);
        assert_eq!(
            app.live_inv_slots[1], (log, 5),
            "the cell the carried stack fills"
        );
        assert_eq!(app.live_inv_carried, (0, 0), "the cursor's own empty");
        assert_eq!(
            app.live_inv_slots[0], (planks, 4),
            "the instant preview the recompute spoke"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, 1, "the cell's own menu id");
                assert_eq!(c.changed, vec![(1, (log, 5)), (0, (planks, 4))]);
                assert_eq!(c.carried, (0, 0));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // (b) THE PLACE REFUSAL: the empty result the carried dirt
        // never takes — no mutation, the packet rides with the empty
        // changed (the mayPlace-false slot's own law)
        let slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        app.live_inventory_updated(slots, Vec::new(), 12, (dirt, 3));
        let (rx, ry) = craft_slot_origin(app.inv_panel, 4);
        app.on_press(rx + 8, ry + 8);
        assert_eq!(
            app.live_inv_carried, (dirt, 3),
            "the carried stack the refusal keeps"
        );
        assert_eq!(app.live_inv_slots[0], (0, 0), "the result stays empty");
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.slot, 0);
                assert_eq!(c.changed, Vec::new(), "no slot the refusal touched");
                assert_eq!(c.carried, (dirt, 3));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
        // (c) THE SWAP REFUSAL: the different carried the non-empty
        // result never swaps — the result the belief keeps
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[0] = (planks, 4);
        app.live_inventory_updated(slots, Vec::new(), 13, (dirt, 2));
        app.on_press(rx + 8, ry + 8);
        assert_eq!(app.live_inv_carried, (dirt, 2), "the cursor untouched");
        assert_eq!(
            app.live_inv_slots[0], (planks, 4),
            "the result the silence keeps"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.changed, Vec::new(), "no slot the silence touched");
                assert_eq!(c.carried, (dirt, 2));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE BATCH'S OWN BELIEF WALK (the shift-press on the result —
    /// the quickMoveStack loop the offline craft_result_quick_move
    /// models): two logs the grid holds, the (planks, 4) verdict TWO
    /// iterations speak — each the store rows take (the merge the
    /// hotbar cell menu 36 keeps, the reverse range the walk speaks),
    /// each the onTake the cell consumes, the spent ingredients the
    /// EMPTY verdict breaks; the changed vec one entry per slot, the
    /// final pair the map law keeps (the store cell the merge filled
    /// twice its LAST pair rides, the re-spoken verdict the diff law
    /// never names); the HUD row the merge follows; the cursor and
    /// the offline store the quickMove never touch.
    #[test]
    fn the_wire_inventory_result_quick_move_batches_the_belief() {
        use crate::world_view::ContainerCommand;
        let mut app = App::new(3);
        app.open(ScreenKind::Connect);
        app.net_world = Some(air_net_world(2, 0));
        app.enter_network_world(None, Skybox::Overworld, None, None);
        let (click_tx, click_rx) = std::sync::mpsc::channel::<ContainerCommand>();
        app.attach_live_clicks(click_tx);
        app.open_inventory();
        app.inv_panel = inventory_panel_origin(640, 360);
        app.on_shift_down(true);
        let log = mc_registry::item_id_by_name("oak_log").unwrap();
        let planks = mc_registry::item_id_by_name("oak_planks").unwrap();
        // the recipe the belief speaks: two logs in the cell menu 1,
        // the result (planks, 4), the hotbar cell menu 36 the merge
        // target (planks, 2) — the batch the two iterations speaks
        let mut slots = [(0, 0); crate::world_view::INVENTORY_MENU_SLOTS];
        slots[1] = (log, 2);
        slots[0] = (planks, 4);
        slots[36] = (planks, 2);
        app.live_inventory_updated(slots, Vec::new(), 14, (0, 0));
        let (rx, ry) = craft_slot_origin(app.inv_panel, 4);
        app.on_press(rx + 8, ry + 8);
        assert_eq!(
            app.live_inv_slots[36], (planks, 10),
            "the merge the two iterations filled"
        );
        assert_eq!(
            app.live_inv_slots[1], (0, 0),
            "the onTake the two logs consumed"
        );
        assert_eq!(
            app.live_inv_slots[0], (0, 0),
            "the spent grid the EMPTY verdict breaks"
        );
        assert_eq!(
            app.hotbar_slots[0], (planks, 10),
            "the HUD row the merge follows"
        );
        assert_eq!(
            app.live_inv_carried, (0, 0),
            "the cursor the quickMove never rides"
        );
        assert_eq!(
            app.inventory.items[12], (0, 0),
            "the offline store the wire world never touches"
        );
        match click_rx.try_recv().expect("the packet rode the lane") {
            ContainerCommand::Click(c) => {
                assert_eq!(c.window_id, 0, "the player's OWN menu the ctor pins");
                assert_eq!(c.state_id, 14, "the revision the feed spoke");
                assert_eq!(c.slot, 0, "the result slot's own menu id");
                assert_eq!(c.input, crate::world_view::ContainerInput::QuickMove);
                assert_eq!(
                    c.changed,
                    vec![(36, (planks, 10)), (1, (0, 0)), (0, (0, 0))],
                    "the batch's own deltas — the store, the cell, the verdict, \
                     the final pairs the map law keeps"
                );
                assert_eq!(c.carried, (0, 0));
            }
            other => panic!("expected a container click, got {other:?}"),
        }
    }

    /// THE FULL STORE'S OWN REFUSAL (the nothing-moved EMPTY the loop
